const FILES={"/":{"body":"<!doctype html>\n<html lang=\"ko\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"description\" content=\"가구 프로필을 저장하고 모집공고의 평형별·유형별 실제 물량을 계산하는 청약 전략 계산기\">\n  <title>우리집 청약 전략실</title>\n  <link rel=\"stylesheet\" href=\"./styles.css\">\n</head>\n<body>\n  <header class=\"hero\">\n    <div class=\"hero-inner\">\n      <div>\n        <div class=\"eyebrow\">민영주택 · 가구 통합 분석</div>\n        <h1>우리집 청약 전략실</h1>\n        <p>가구 정보는 한 번 저장하고, 모집공고만 바꿔 실제 좌석과 신청 조합을 다시 계산합니다.</p>\n      </div>\n      <div class=\"privacy\"><span>●</span> PDF와 가족정보는 이 기기 안에서만 처리</div>\n    </div>\n  </header>\n\n  <main class=\"shell\">\n    <nav class=\"steps\" aria-label=\"계산 단계\">\n      <button class=\"step active\" data-panel=\"profile\"><b>1</b><span>나의 프로필</span><small>한 번 저장</small></button>\n      <button class=\"step\" data-panel=\"notice\"><b>2</b><span>모집공고</span><small>PDF 분석·검수</small></button>\n      <button class=\"step\" data-panel=\"strategy\"><b>3</b><span>좌석·전략</span><small>신청 조합 추천</small></button>\n    </nav>\n\n    <section id=\"profile\" class=\"panel active\">\n      <div class=\"section-head\">\n        <div><span class=\"kicker\">HOUSEHOLD PROFILE</span><h2>나의 청약 프로필</h2></div>\n        <div class=\"save-state\" id=\"profileSaveState\">이 기기에 자동 저장됩니다</div>\n      </div>\n\n      <article class=\"card profile-type-card\">\n        <div class=\"card-head\">\n          <div><h3>법적 혼인·가구 유형</h3><p>공고일 현재 법적 상태를 선택하면 필요한 입력란과 특공 자격을 자동 분기합니다.</p></div>\n          <span id=\"derivedProfileBadge\" class=\"badge ok\">프로필 판정</span>\n        </div>\n        <div class=\"profile-options\">\n          <label><input type=\"radio\" name=\"profileType\" value=\"single\" checked><span><b>미혼·자녀 없음</b><small>1인 가구 포함</small></span></label>\n          <label><input type=\"radio\" name=\"profileType\" value=\"single_parent\"><span><b>미혼·자녀 있음</b><small>한부모 포함</small></span></label>\n          <label><input type=\"radio\" name=\"profileType\" value=\"engaged\"><span><b>혼인 예정·미신고</b><small>예비부부·동거</small></span></label>\n          <label><input type=\"radio\" name=\"profileType\" value=\"married\"><span><b>법률혼</b><small>7년 여부 자동 계산</small></span></label>\n          <label><input type=\"radio\" name=\"profileType\" value=\"former\"><span><b>이혼·사별 등</b><small>현재 법적 배우자 없음</small></span></label>\n        </div>\n        <div class=\"profile-subfields\">\n          <label id=\"singleHouseholdKindField\">1인 가구 세대 유형<select id=\"singleHouseholdKind\"><option value=\"solo\">단독세대 · 전용 60㎡ 이하만</option><option value=\"not_solo\">비단독세대 · 부모 등 세대구성원과 동거</option></select></label>\n          <label id=\"unmarriedChildRegisteredField\" class=\"checkline is-hidden\"><input id=\"unmarriedChildRegistered\" type=\"checkbox\" checked> 미혼 자녀가 신청자 주민등록표등본에 함께 등재됨</label>\n        </div>\n        <div id=\"profileTypeNote\" class=\"profile-note\"></div>\n      </article>\n\n      <div class=\"grid two\">\n        <article class=\"card\">\n          <h3>세대·거주</h3>\n          <label>현재 거주 시·도<input id=\"residenceRegion\" value=\"서울특별시\" placeholder=\"예: 서울특별시\"></label>\n          <label>해당 시·도 연속 거주 시작일<input id=\"residenceStart\" type=\"text\" class=\"manual-date\" inputmode=\"numeric\" placeholder=\"YYYY.MM.DD\" autocomplete=\"off\"></label>\n          <label id=\"lastHomeDisposalField\" class=\"is-hidden\">신청자·배우자의 최근 주택 처분일<input id=\"lastHomeDisposal\" type=\"text\" class=\"manual-date\" inputmode=\"numeric\" placeholder=\"YYYY.MM.DD\" autocomplete=\"off\"></label>\n          <div class=\"checks\">\n            <label><input id=\"noHome\" type=\"checkbox\" checked> 무주택세대구성원</label>\n            <label><input id=\"neverHome\" type=\"checkbox\" checked> 세대 전원이 과거 주택소유 없음</label>\n            <label><input id=\"specialClean\" type=\"checkbox\" checked> 특별공급 1회 제한 문제 없음</label>\n            <label><input id=\"reWinClean\" type=\"checkbox\" checked> 재당첨·과거 5년 당첨 제한 문제 없음</label>\n          </div>\n        </article>\n\n        <article class=\"card\">\n          <h3>혼인·자녀</h3>\n          <div class=\"form-grid\">\n            <label id=\"marriageDateField\">혼인신고일<input id=\"marriageDate\" type=\"text\" class=\"manual-date\" inputmode=\"numeric\" placeholder=\"YYYY.MM.DD\" autocomplete=\"off\"></label>\n            <label>출생한 미성년 자녀 수<input id=\"children\" type=\"number\" min=\"0\" value=\"0\"></label>\n            <label>임신 중 태아 수<input id=\"fetuses\" type=\"number\" min=\"0\" value=\"0\"></label>\n            <label>혼인 중 출생·임신한 자녀 수<input id=\"marriageChildren\" type=\"number\" min=\"0\" value=\"0\"></label>\n            <label>출생한 만 6세 미만 자녀 수<input id=\"infants\" type=\"number\" min=\"0\" value=\"0\"></label>\n            <label>막내 출생일<input id=\"youngestBirth\" type=\"text\" class=\"manual-date\" inputmode=\"numeric\" placeholder=\"YYYY.MM.DD\" autocomplete=\"off\"></label>\n          </div>\n          <div class=\"checks\">\n            <label><input id=\"assetOk\" type=\"checkbox\" checked> 공고문상 부동산 자산기준 충족</label>\n          </div>\n          <div id=\"childCountSummary\" class=\"calc-summary\"></div>\n          <p class=\"hint\">태아는 특공의 자녀 수와 소득 가구원 수에는 포함하지만, 일반공급 부양가족은 주민등록표 기준으로 별도 판정합니다.</p>\n        </article>\n      </div>\n\n      <article class=\"card income-card\">\n        <div class=\"card-head\">\n          <div><h3>도시근로자 월평균소득 자동 계산</h3><p>월계 공고문에 실린 2025년도 기준표를 고정 적용합니다.</p></div>\n          <span class=\"badge ok\">2025 소득표</span>\n        </div>\n        <div class=\"form-grid four\">\n          <label>소득 산정 가구원 수<input id=\"householdSize\" type=\"number\" min=\"1\" value=\"1\"></label>\n          <label>가구원 수 자동 제안<select id=\"householdSizeAuto\"><option value=\"yes\">자동 계산</option><option value=\"no\">직접 입력</option></select></label>\n          <label>신청자 A 월소득<input id=\"aMonthlyIncome\" type=\"number\" min=\"0\" step=\"10000\" value=\"0\"><span class=\"suffix\">원</span></label>\n          <label id=\"bIncomeField\">신청자 B 월소득<input id=\"bMonthlyIncome\" type=\"number\" min=\"0\" step=\"10000\" value=\"0\"><span class=\"suffix\">원</span></label>\n        </div>\n        <div id=\"incomeSummary\" class=\"income-summary\"></div>\n        <p class=\"hint\">입력 월소득은 공고문이 요구하는 전년도 소득자료 기준으로 맞춰야 합니다. 실제 심사에는 세대구성원별 소득자료와 자산요건이 함께 적용됩니다.</p>\n      </article>\n\n      <div class=\"grid two people\">\n        <article class=\"card person person-a\">\n          <div class=\"person-title\"><span>A</span><h3>신청자 A</h3></div>\n          <div class=\"form-grid\">\n            <label>청약통장 가입일<input id=\"aAccount\" type=\"text\" class=\"manual-date\" inputmode=\"numeric\" placeholder=\"YYYY.MM.DD\" autocomplete=\"off\"></label>\n            <label>생년월일<input id=\"aBirth\" type=\"text\" class=\"manual-date\" inputmode=\"numeric\" placeholder=\"YYYY.MM.DD\" autocomplete=\"off\"></label>\n            <label>추가 인정 부양가족 수<input id=\"aOtherDependents\" type=\"number\" min=\"0\" value=\"0\"><span class=\"field-help\">직계존속·성년 미혼자녀 등</span></label>\n          </div>\n          <div class=\"score-results\">\n            <div><span>일반공급 가점</span><output id=\"aGeneralScore\">자동 계산</output><small id=\"aGeneralBreakdown\"></small></div>\n            <div><span>다자녀 배점</span><output id=\"aMultiScore\">자동 계산</output><small id=\"aMultiBreakdown\"></small></div>\n          </div>\n          <div class=\"checks compact\">\n            <label><input id=\"aHead\" type=\"checkbox\" checked> 세대주</label>\n            <label><input id=\"aDeposit\" type=\"checkbox\" checked> 지역·면적별 예치금 충족</label>\n            <label><input id=\"aTax5\" type=\"checkbox\" checked> 소득세 5년 이상</label>\n            <label><input id=\"aElder3\" type=\"checkbox\"> 65세 이상 직계존속 3년 부양</label>\n            <label><input id=\"aElderNoHome\" type=\"checkbox\"> 피부양 노부모 부부 모두 무주택</label>\n            <label><input id=\"aAgency\" type=\"checkbox\"> 기관추천 대상 확인 완료</label>\n            <label><input id=\"aThreeGeneration\" type=\"checkbox\"> 3세대 이상 3년 계속 동거</label>\n            <label><input id=\"aSingleParent5\" type=\"checkbox\"> 법정 한부모가족 5년 경과</label>\n          </div>\n        </article>\n\n        <article id=\"personBCard\" class=\"card person person-b\">\n          <div class=\"person-title\"><span>B</span><h3 id=\"personBTitle\">신청자 B</h3></div>\n          <div class=\"form-grid\">\n            <label>청약통장 가입일<input id=\"bAccount\" type=\"text\" class=\"manual-date\" inputmode=\"numeric\" placeholder=\"YYYY.MM.DD\" autocomplete=\"off\"></label>\n            <label>생년월일<input id=\"bBirth\" type=\"text\" class=\"manual-date\" inputmode=\"numeric\" placeholder=\"YYYY.MM.DD\" autocomplete=\"off\"></label>\n            <label>추가 인정 부양가족 수<input id=\"bOtherDependents\" type=\"number\" min=\"0\" value=\"0\"><span class=\"field-help\">직계존속·성년 미혼자녀 등</span></label>\n          </div>\n          <div class=\"score-results\">\n            <div><span>일반공급 가점</span><output id=\"bGeneralScore\">자동 계산</output><small id=\"bGeneralBreakdown\"></small></div>\n            <div><span>다자녀 배점</span><output id=\"bMultiScore\">자동 계산</output><small id=\"bMultiBreakdown\"></small></div>\n          </div>\n          <div class=\"checks compact\">\n            <label><input id=\"bHead\" type=\"checkbox\"> 세대주</label>\n            <label><input id=\"bDeposit\" type=\"checkbox\" checked> 지역·면적별 예치금 충족</label>\n            <label><input id=\"bTax5\" type=\"checkbox\" checked> 소득세 5년 이상</label>\n            <label><input id=\"bElder3\" type=\"checkbox\"> 65세 이상 직계존속 3년 부양</label>\n            <label><input id=\"bElderNoHome\" type=\"checkbox\"> 피부양 노부모 부부 모두 무주택</label>\n            <label><input id=\"bAgency\" type=\"checkbox\"> 기관추천 대상 확인 완료</label>\n            <label><input id=\"bThreeGeneration\" type=\"checkbox\"> 3세대 이상 3년 계속 동거</label>\n            <label><input id=\"bSingleParent5\" type=\"checkbox\"> 법정 한부모가족 5년 경과</label>\n          </div>\n        </article>\n      </div>\n      <div class=\"actions end\"><button class=\"primary\" data-go=\"notice\">저장하고 모집공고 넣기 →</button></div>\n    </section>\n\n    <section id=\"notice\" class=\"panel\">\n      <div class=\"section-head\">\n        <div><span class=\"kicker\">ANNOUNCEMENT</span><h2>모집공고 불러오기</h2></div>\n        <div id=\"verifiedBadge\" class=\"badge warn\">검수 필요</div>\n      </div>\n\n      <div class=\"import-card\">\n        <div>\n          <strong>입주자모집공고 PDF</strong>\n          <p>단지명, 공고일, 실제 전용면적, 평형별 특별·일반공급 물량을 자동으로 읽습니다.</p>\n        </div>\n        <label class=\"file-button\">PDF 선택<input id=\"pdfFile\" type=\"file\" accept=\"application/pdf,.pdf\"></label>\n        <div id=\"parseStatus\" class=\"parse-status\">현재 월계 중흥S-클래스 예시가 들어 있습니다.</div>\n      </div>\n\n      <div class=\"notice-toolbar\">\n        <label>저장된 공고<select id=\"noticeLibrary\"></select></label>\n        <button id=\"blankNotice\" class=\"ghost\">빈 공고 만들기</button>\n        <button id=\"saveNotice\" class=\"ghost\">현재 공고 저장</button>\n        <button id=\"exportNotice\" class=\"ghost\">JSON 내보내기</button>\n        <label class=\"ghost file-inline\">JSON 불러오기<input id=\"jsonFile\" type=\"file\" accept=\".json,application/json\"></label>\n      </div>\n\n      <article class=\"card\">\n        <h3>공고 핵심정보</h3>\n        <div class=\"form-grid four\">\n          <label>단지명<input id=\"projectName\"></label>\n          <label>입주자모집공고일<input id=\"noticeDate\" type=\"text\" class=\"manual-date\" inputmode=\"numeric\" placeholder=\"YYYY.MM.DD\" autocomplete=\"off\"></label>\n          <label>공급지역<input id=\"location\"></label>\n          <label>주택유형<select id=\"housingType\"><option value=\"private\">민영주택</option><option value=\"public\">국민·공공주택</option><option value=\"unsupported\">기타/검토 필요</option></select></label>\n          <label>지역우선 기준지역<input id=\"priorityRegion\" placeholder=\"예: 서울특별시\"></label>\n          <label>지역우선 거주기간<input id=\"priorityYears\" type=\"number\" min=\"0\" step=\".5\" value=\"2\"><span class=\"suffix\">년</span></label>\n          <label>특공 통장 최소기간<input id=\"specialMonths\" type=\"number\" min=\"0\" value=\"6\"><span class=\"suffix\">개월</span></label>\n          <label>일반 1순위 통장기간<input id=\"generalMonths\" type=\"number\" min=\"0\" value=\"24\"><span class=\"suffix\">개월</span></label>\r\n          <label>일반 1순위 세대주 요건<select id=\"generalHeadRequired\"><option value=\"yes\">세대주 필요</option><option value=\"no\">세대원도 가능</option></select></label>\n        </div>\n      </article>\n\n      <article class=\"card\">\n        <div class=\"card-head\">\n          <div><h3>평형별 공급물량</h3><p>자동 추출값을 공고문 표와 한 번 대조해 주세요.</p></div>\n          <button id=\"addSize\" class=\"ghost\">+ 평형 추가</button>\n        </div>\n        <div class=\"table-wrap\"><table class=\"supply-table\">\n          <thead><tr><th>주택형</th><th>실제 전용㎡</th><th>총</th><th>기관</th><th>다자녀</th><th>신혼</th><th>노부모</th><th>생애최초</th><th>신생아</th><th>일반</th><th></th></tr></thead>\n          <tbody id=\"supplyRows\"></tbody>\n          <tfoot id=\"supplyTotal\"></tfoot>\n        </table></div>\n      </article>\n\n      <article class=\"card rule-card\">\n        <div class=\"card-head\">\n          <div><h3>일반공급 가점제 비율</h3><p>공고문·규제지역 판정을 우선하며 자동값은 반드시 확인합니다.</p></div>\n          <span class=\"law-date\">기준: 공고일 적용 규칙</span>\n        </div>\n        <div class=\"rate-grid\">\n          <label>60㎡ 이하<input id=\"pointRateSmall\" type=\"number\" min=\"0\" max=\"100\" value=\"40\"><span class=\"suffix\">%</span></label>\n          <label>60㎡ 초과~85㎡ 이하<input id=\"pointRateMedium\" type=\"number\" min=\"0\" max=\"100\" value=\"70\"><span class=\"suffix\">%</span></label>\n          <label>85㎡ 초과<input id=\"pointRateLarge\" type=\"number\" min=\"0\" max=\"100\" value=\"80\"><span class=\"suffix\">%</span></label>\n        </div>\n        <p class=\"formula\">가점 좌석 = 올림(일반공급 × 가점비율) · 추첨 좌석 = 나머지 · 추첨 중 무주택 우선 = 올림(추첨 × 75%)</p>\n      </article>\n\n      <div class=\"actions split\">\n        <button class=\"ghost\" data-go=\"profile\">← 프로필 정보</button>\n        <button id=\"confirmNotice\" class=\"primary\">숫자 검수 완료하고 좌석 계산 →</button>\n      </div>\n    </section>\n\n    <section id=\"strategy\" class=\"panel\">\n      <div class=\"section-head\">\n        <div><span class=\"kicker\">SEAT & STRATEGY</span><h2>실제 좌석과 가구 전략</h2></div>\n        <button class=\"ghost\" data-go=\"notice\">공고 수정</button>\n      </div>\n\n      <div class=\"strategy-settings card\">\n        <label>최소 전용면적<input id=\"minArea\" type=\"number\" min=\"0\" value=\"36\"><span class=\"suffix\">㎡</span></label>\n        <label>전략 성향<select id=\"mode\"><option value=\"probability\">당첨기회 우선</option><option value=\"balance\" selected>실거주·기회 균형</option><option value=\"quality\">면적 우선</option></select></label>\n        <label id=\"bothApplyField\" class=\"checkline\"><input id=\"bothApply\" type=\"checkbox\" checked> 신청자 A·B 모두 신청</label>\n        <label class=\"checkline\"><input id=\"allowSpecialGeneral\" type=\"checkbox\" checked> 각자 특공+일반 동시신청</label>\n        <label class=\"checkline\"><input id=\"diversify\" type=\"checkbox\" checked> 신청자간 평형 분산</label>\n        <button id=\"calculate\" class=\"primary\">전략 다시 계산</button>\n      </div>\n\n      <div id=\"strategyWarning\"></div>\n      <div id=\"recommendation\"></div>\n\n      <article class=\"card result-card\">\n        <div class=\"card-head\"><div><span class=\"kicker\">GENERAL SUPPLY</span><h3>일반공급 실제 좌석</h3></div><span class=\"rounding\">소수점 올림 반영</span></div>\n        <div id=\"generalSeats\" class=\"table-wrap\"></div>\n      </article>\n\n      <article class=\"card result-card\">\n        <div class=\"card-head\"><div><span class=\"kicker\">SPECIAL SUPPLY</span><h3>특별공급 단계별 실제 좌석</h3></div><span class=\"rounding\">50% → 20% → 나머지</span></div>\n        <div id=\"specialSeats\" class=\"table-wrap\"></div>\n      </article>\n\n      <div class=\"grid two\">\n        <article class=\"card result-card\"><h3>신청자별 신청 후보 순위</h3><div id=\"candidateTable\" class=\"table-wrap\"></div></article>\n        <article class=\"card result-card\"><h3>자격 체크</h3><div id=\"eligibilityTable\" class=\"table-wrap\"></div></article>\n      </div>\n\n      <details class=\"legal-note\">\n        <summary>계산 원칙과 꼭 확인할 점</summary>\n        <div>\n          <p>이 계산기는 모집공고 물량을 법정 비율로 좌석화하고 상대적인 전략 우선순위를 비교합니다. 경쟁률이나 실제 당첨확률을 예측하지 않습니다.</p>\n          <p>특별공급 각 단계의 미달 좌석과 낙첨자는 다음 단계로 넘어가므로 실제 접수결과에 따라 후속 단계 좌석은 늘 수 있습니다. 최종 신청 전 청약Home과 사업주체에 자격을 확인하세요.</p>\n        </div>\n      </details>\n    </section>\n  </main>\n\n  <div id=\"toast\" class=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n  <script src=\"./rules.js\"></script>\n  <script src=\"./app.js\"></script>\n</body>\n</html>\n","type":"text/html; charset=utf-8"},"/index.html":{"body":"<!doctype html>\n<html lang=\"ko\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"description\" content=\"가구 프로필을 저장하고 모집공고의 평형별·유형별 실제 물량을 계산하는 청약 전략 계산기\">\n  <title>우리집 청약 전략실</title>\n  <link rel=\"stylesheet\" href=\"./styles.css\">\n</head>\n<body>\n  <header class=\"hero\">\n    <div class=\"hero-inner\">\n      <div>\n        <div class=\"eyebrow\">민영주택 · 가구 통합 분석</div>\n        <h1>우리집 청약 전략실</h1>\n        <p>가구 정보는 한 번 저장하고, 모집공고만 바꿔 실제 좌석과 신청 조합을 다시 계산합니다.</p>\n      </div>\n      <div class=\"privacy\"><span>●</span> PDF와 가족정보는 이 기기 안에서만 처리</div>\n    </div>\n  </header>\n\n  <main class=\"shell\">\n    <nav class=\"steps\" aria-label=\"계산 단계\">\n      <button class=\"step active\" data-panel=\"profile\"><b>1</b><span>나의 프로필</span><small>한 번 저장</small></button>\n      <button class=\"step\" data-panel=\"notice\"><b>2</b><span>모집공고</span><small>PDF 분석·검수</small></button>\n      <button class=\"step\" data-panel=\"strategy\"><b>3</b><span>좌석·전략</span><small>신청 조합 추천</small></button>\n    </nav>\n\n    <section id=\"profile\" class=\"panel active\">\n      <div class=\"section-head\">\n        <div><span class=\"kicker\">HOUSEHOLD PROFILE</span><h2>나의 청약 프로필</h2></div>\n        <div class=\"save-state\" id=\"profileSaveState\">이 기기에 자동 저장됩니다</div>\n      </div>\n\n      <article class=\"card profile-type-card\">\n        <div class=\"card-head\">\n          <div><h3>법적 혼인·가구 유형</h3><p>공고일 현재 법적 상태를 선택하면 필요한 입력란과 특공 자격을 자동 분기합니다.</p></div>\n          <span id=\"derivedProfileBadge\" class=\"badge ok\">프로필 판정</span>\n        </div>\n        <div class=\"profile-options\">\n          <label><input type=\"radio\" name=\"profileType\" value=\"single\" checked><span><b>미혼·자녀 없음</b><small>1인 가구 포함</small></span></label>\n          <label><input type=\"radio\" name=\"profileType\" value=\"single_parent\"><span><b>미혼·자녀 있음</b><small>한부모 포함</small></span></label>\n          <label><input type=\"radio\" name=\"profileType\" value=\"engaged\"><span><b>혼인 예정·미신고</b><small>예비부부·동거</small></span></label>\n          <label><input type=\"radio\" name=\"profileType\" value=\"married\"><span><b>법률혼</b><small>7년 여부 자동 계산</small></span></label>\n          <label><input type=\"radio\" name=\"profileType\" value=\"former\"><span><b>이혼·사별 등</b><small>현재 법적 배우자 없음</small></span></label>\n        </div>\n        <div class=\"profile-subfields\">\n          <label id=\"singleHouseholdKindField\">1인 가구 세대 유형<select id=\"singleHouseholdKind\"><option value=\"solo\">단독세대 · 전용 60㎡ 이하만</option><option value=\"not_solo\">비단독세대 · 부모 등 세대구성원과 동거</option></select></label>\n          <label id=\"unmarriedChildRegisteredField\" class=\"checkline is-hidden\"><input id=\"unmarriedChildRegistered\" type=\"checkbox\" checked> 미혼 자녀가 신청자 주민등록표등본에 함께 등재됨</label>\n        </div>\n        <div id=\"profileTypeNote\" class=\"profile-note\"></div>\n      </article>\n\n      <div class=\"grid two\">\n        <article class=\"card\">\n          <h3>세대·거주</h3>\n          <label>현재 거주 시·도<input id=\"residenceRegion\" value=\"서울특별시\" placeholder=\"예: 서울특별시\"></label>\n          <label>해당 시·도 연속 거주 시작일<input id=\"residenceStart\" type=\"text\" class=\"manual-date\" inputmode=\"numeric\" placeholder=\"YYYY.MM.DD\" autocomplete=\"off\"></label>\n          <label id=\"lastHomeDisposalField\" class=\"is-hidden\">신청자·배우자의 최근 주택 처분일<input id=\"lastHomeDisposal\" type=\"text\" class=\"manual-date\" inputmode=\"numeric\" placeholder=\"YYYY.MM.DD\" autocomplete=\"off\"></label>\n          <div class=\"checks\">\n            <label><input id=\"noHome\" type=\"checkbox\" checked> 무주택세대구성원</label>\n            <label><input id=\"neverHome\" type=\"checkbox\" checked> 세대 전원이 과거 주택소유 없음</label>\n            <label><input id=\"specialClean\" type=\"checkbox\" checked> 특별공급 1회 제한 문제 없음</label>\n            <label><input id=\"reWinClean\" type=\"checkbox\" checked> 재당첨·과거 5년 당첨 제한 문제 없음</label>\n          </div>\n        </article>\n\n        <article class=\"card\">\n          <h3>혼인·자녀</h3>\n          <div class=\"form-grid\">\n            <label id=\"marriageDateField\">혼인신고일<input id=\"marriageDate\" type=\"text\" class=\"manual-date\" inputmode=\"numeric\" placeholder=\"YYYY.MM.DD\" autocomplete=\"off\"></label>\n            <label>출생한 미성년 자녀 수<input id=\"children\" type=\"number\" min=\"0\" value=\"0\"></label>\n            <label>임신 중 태아 수<input id=\"fetuses\" type=\"number\" min=\"0\" value=\"0\"></label>\n            <label>혼인 중 출생·임신한 자녀 수<input id=\"marriageChildren\" type=\"number\" min=\"0\" value=\"0\"></label>\n            <label>출생한 만 6세 미만 자녀 수<input id=\"infants\" type=\"number\" min=\"0\" value=\"0\"></label>\n            <label>막내 출생일<input id=\"youngestBirth\" type=\"text\" class=\"manual-date\" inputmode=\"numeric\" placeholder=\"YYYY.MM.DD\" autocomplete=\"off\"></label>\n          </div>\n          <div class=\"checks\">\n            <label><input id=\"assetOk\" type=\"checkbox\" checked> 공고문상 부동산 자산기준 충족</label>\n          </div>\n          <div id=\"childCountSummary\" class=\"calc-summary\"></div>\n          <p class=\"hint\">태아는 특공의 자녀 수와 소득 가구원 수에는 포함하지만, 일반공급 부양가족은 주민등록표 기준으로 별도 판정합니다.</p>\n        </article>\n      </div>\n\n      <article class=\"card income-card\">\n        <div class=\"card-head\">\n          <div><h3>도시근로자 월평균소득 자동 계산</h3><p>월계 공고문에 실린 2025년도 기준표를 고정 적용합니다.</p></div>\n          <span class=\"badge ok\">2025 소득표</span>\n        </div>\n        <div class=\"form-grid four\">\n          <label>소득 산정 가구원 수<input id=\"householdSize\" type=\"number\" min=\"1\" value=\"1\"></label>\n          <label>가구원 수 자동 제안<select id=\"householdSizeAuto\"><option value=\"yes\">자동 계산</option><option value=\"no\">직접 입력</option></select></label>\n          <label>신청자 A 월소득<input id=\"aMonthlyIncome\" type=\"number\" min=\"0\" step=\"10000\" value=\"0\"><span class=\"suffix\">원</span></label>\n          <label id=\"bIncomeField\">신청자 B 월소득<input id=\"bMonthlyIncome\" type=\"number\" min=\"0\" step=\"10000\" value=\"0\"><span class=\"suffix\">원</span></label>\n        </div>\n        <div id=\"incomeSummary\" class=\"income-summary\"></div>\n        <p class=\"hint\">입력 월소득은 공고문이 요구하는 전년도 소득자료 기준으로 맞춰야 합니다. 실제 심사에는 세대구성원별 소득자료와 자산요건이 함께 적용됩니다.</p>\n      </article>\n\n      <div class=\"grid two people\">\n        <article class=\"card person person-a\">\n          <div class=\"person-title\"><span>A</span><h3>신청자 A</h3></div>\n          <div class=\"form-grid\">\n            <label>청약통장 가입일<input id=\"aAccount\" type=\"text\" class=\"manual-date\" inputmode=\"numeric\" placeholder=\"YYYY.MM.DD\" autocomplete=\"off\"></label>\n            <label>생년월일<input id=\"aBirth\" type=\"text\" class=\"manual-date\" inputmode=\"numeric\" placeholder=\"YYYY.MM.DD\" autocomplete=\"off\"></label>\n            <label>추가 인정 부양가족 수<input id=\"aOtherDependents\" type=\"number\" min=\"0\" value=\"0\"><span class=\"field-help\">직계존속·성년 미혼자녀 등</span></label>\n          </div>\n          <div class=\"score-results\">\n            <div><span>일반공급 가점</span><output id=\"aGeneralScore\">자동 계산</output><small id=\"aGeneralBreakdown\"></small></div>\n            <div><span>다자녀 배점</span><output id=\"aMultiScore\">자동 계산</output><small id=\"aMultiBreakdown\"></small></div>\n          </div>\n          <div class=\"checks compact\">\n            <label><input id=\"aHead\" type=\"checkbox\" checked> 세대주</label>\n            <label><input id=\"aDeposit\" type=\"checkbox\" checked> 지역·면적별 예치금 충족</label>\n            <label><input id=\"aTax5\" type=\"checkbox\" checked> 소득세 5년 이상</label>\n            <label><input id=\"aElder3\" type=\"checkbox\"> 65세 이상 직계존속 3년 부양</label>\n            <label><input id=\"aElderNoHome\" type=\"checkbox\"> 피부양 노부모 부부 모두 무주택</label>\n            <label><input id=\"aAgency\" type=\"checkbox\"> 기관추천 대상 확인 완료</label>\n            <label><input id=\"aThreeGeneration\" type=\"checkbox\"> 3세대 이상 3년 계속 동거</label>\n            <label><input id=\"aSingleParent5\" type=\"checkbox\"> 법정 한부모가족 5년 경과</label>\n          </div>\n        </article>\n\n        <article id=\"personBCard\" class=\"card person person-b\">\n          <div class=\"person-title\"><span>B</span><h3 id=\"personBTitle\">신청자 B</h3></div>\n          <div class=\"form-grid\">\n            <label>청약통장 가입일<input id=\"bAccount\" type=\"text\" class=\"manual-date\" inputmode=\"numeric\" placeholder=\"YYYY.MM.DD\" autocomplete=\"off\"></label>\n            <label>생년월일<input id=\"bBirth\" type=\"text\" class=\"manual-date\" inputmode=\"numeric\" placeholder=\"YYYY.MM.DD\" autocomplete=\"off\"></label>\n            <label>추가 인정 부양가족 수<input id=\"bOtherDependents\" type=\"number\" min=\"0\" value=\"0\"><span class=\"field-help\">직계존속·성년 미혼자녀 등</span></label>\n          </div>\n          <div class=\"score-results\">\n            <div><span>일반공급 가점</span><output id=\"bGeneralScore\">자동 계산</output><small id=\"bGeneralBreakdown\"></small></div>\n            <div><span>다자녀 배점</span><output id=\"bMultiScore\">자동 계산</output><small id=\"bMultiBreakdown\"></small></div>\n          </div>\n          <div class=\"checks compact\">\n            <label><input id=\"bHead\" type=\"checkbox\"> 세대주</label>\n            <label><input id=\"bDeposit\" type=\"checkbox\" checked> 지역·면적별 예치금 충족</label>\n            <label><input id=\"bTax5\" type=\"checkbox\" checked> 소득세 5년 이상</label>\n            <label><input id=\"bElder3\" type=\"checkbox\"> 65세 이상 직계존속 3년 부양</label>\n            <label><input id=\"bElderNoHome\" type=\"checkbox\"> 피부양 노부모 부부 모두 무주택</label>\n            <label><input id=\"bAgency\" type=\"checkbox\"> 기관추천 대상 확인 완료</label>\n            <label><input id=\"bThreeGeneration\" type=\"checkbox\"> 3세대 이상 3년 계속 동거</label>\n            <label><input id=\"bSingleParent5\" type=\"checkbox\"> 법정 한부모가족 5년 경과</label>\n          </div>\n        </article>\n      </div>\n      <div class=\"actions end\"><button class=\"primary\" data-go=\"notice\">저장하고 모집공고 넣기 →</button></div>\n    </section>\n\n    <section id=\"notice\" class=\"panel\">\n      <div class=\"section-head\">\n        <div><span class=\"kicker\">ANNOUNCEMENT</span><h2>모집공고 불러오기</h2></div>\n        <div id=\"verifiedBadge\" class=\"badge warn\">검수 필요</div>\n      </div>\n\n      <div class=\"import-card\">\n        <div>\n          <strong>입주자모집공고 PDF</strong>\n          <p>단지명, 공고일, 실제 전용면적, 평형별 특별·일반공급 물량을 자동으로 읽습니다.</p>\n        </div>\n        <label class=\"file-button\">PDF 선택<input id=\"pdfFile\" type=\"file\" accept=\"application/pdf,.pdf\"></label>\n        <div id=\"parseStatus\" class=\"parse-status\">현재 월계 중흥S-클래스 예시가 들어 있습니다.</div>\n      </div>\n\n      <div class=\"notice-toolbar\">\n        <label>저장된 공고<select id=\"noticeLibrary\"></select></label>\n        <button id=\"blankNotice\" class=\"ghost\">빈 공고 만들기</button>\n        <button id=\"saveNotice\" class=\"ghost\">현재 공고 저장</button>\n        <button id=\"exportNotice\" class=\"ghost\">JSON 내보내기</button>\n        <label class=\"ghost file-inline\">JSON 불러오기<input id=\"jsonFile\" type=\"file\" accept=\".json,application/json\"></label>\n      </div>\n\n      <article class=\"card\">\n        <h3>공고 핵심정보</h3>\n        <div class=\"form-grid four\">\n          <label>단지명<input id=\"projectName\"></label>\n          <label>입주자모집공고일<input id=\"noticeDate\" type=\"text\" class=\"manual-date\" inputmode=\"numeric\" placeholder=\"YYYY.MM.DD\" autocomplete=\"off\"></label>\n          <label>공급지역<input id=\"location\"></label>\n          <label>주택유형<select id=\"housingType\"><option value=\"private\">민영주택</option><option value=\"public\">국민·공공주택</option><option value=\"unsupported\">기타/검토 필요</option></select></label>\n          <label>지역우선 기준지역<input id=\"priorityRegion\" placeholder=\"예: 서울특별시\"></label>\n          <label>지역우선 거주기간<input id=\"priorityYears\" type=\"number\" min=\"0\" step=\".5\" value=\"2\"><span class=\"suffix\">년</span></label>\n          <label>특공 통장 최소기간<input id=\"specialMonths\" type=\"number\" min=\"0\" value=\"6\"><span class=\"suffix\">개월</span></label>\n          <label>일반 1순위 통장기간<input id=\"generalMonths\" type=\"number\" min=\"0\" value=\"24\"><span class=\"suffix\">개월</span></label>\r\n          <label>일반 1순위 세대주 요건<select id=\"generalHeadRequired\"><option value=\"yes\">세대주 필요</option><option value=\"no\">세대원도 가능</option></select></label>\n        </div>\n      </article>\n\n      <article class=\"card\">\n        <div class=\"card-head\">\n          <div><h3>평형별 공급물량</h3><p>자동 추출값을 공고문 표와 한 번 대조해 주세요.</p></div>\n          <button id=\"addSize\" class=\"ghost\">+ 평형 추가</button>\n        </div>\n        <div class=\"table-wrap\"><table class=\"supply-table\">\n          <thead><tr><th>주택형</th><th>실제 전용㎡</th><th>총</th><th>기관</th><th>다자녀</th><th>신혼</th><th>노부모</th><th>생애최초</th><th>신생아</th><th>일반</th><th></th></tr></thead>\n          <tbody id=\"supplyRows\"></tbody>\n          <tfoot id=\"supplyTotal\"></tfoot>\n        </table></div>\n      </article>\n\n      <article class=\"card rule-card\">\n        <div class=\"card-head\">\n          <div><h3>일반공급 가점제 비율</h3><p>공고문·규제지역 판정을 우선하며 자동값은 반드시 확인합니다.</p></div>\n          <span class=\"law-date\">기준: 공고일 적용 규칙</span>\n        </div>\n        <div class=\"rate-grid\">\n          <label>60㎡ 이하<input id=\"pointRateSmall\" type=\"number\" min=\"0\" max=\"100\" value=\"40\"><span class=\"suffix\">%</span></label>\n          <label>60㎡ 초과~85㎡ 이하<input id=\"pointRateMedium\" type=\"number\" min=\"0\" max=\"100\" value=\"70\"><span class=\"suffix\">%</span></label>\n          <label>85㎡ 초과<input id=\"pointRateLarge\" type=\"number\" min=\"0\" max=\"100\" value=\"80\"><span class=\"suffix\">%</span></label>\n        </div>\n        <p class=\"formula\">가점 좌석 = 올림(일반공급 × 가점비율) · 추첨 좌석 = 나머지 · 추첨 중 무주택 우선 = 올림(추첨 × 75%)</p>\n      </article>\n\n      <div class=\"actions split\">\n        <button class=\"ghost\" data-go=\"profile\">← 프로필 정보</button>\n        <button id=\"confirmNotice\" class=\"primary\">숫자 검수 완료하고 좌석 계산 →</button>\n      </div>\n    </section>\n\n    <section id=\"strategy\" class=\"panel\">\n      <div class=\"section-head\">\n        <div><span class=\"kicker\">SEAT & STRATEGY</span><h2>실제 좌석과 가구 전략</h2></div>\n        <button class=\"ghost\" data-go=\"notice\">공고 수정</button>\n      </div>\n\n      <div class=\"strategy-settings card\">\n        <label>최소 전용면적<input id=\"minArea\" type=\"number\" min=\"0\" value=\"36\"><span class=\"suffix\">㎡</span></label>\n        <label>전략 성향<select id=\"mode\"><option value=\"probability\">당첨기회 우선</option><option value=\"balance\" selected>실거주·기회 균형</option><option value=\"quality\">면적 우선</option></select></label>\n        <label id=\"bothApplyField\" class=\"checkline\"><input id=\"bothApply\" type=\"checkbox\" checked> 신청자 A·B 모두 신청</label>\n        <label class=\"checkline\"><input id=\"allowSpecialGeneral\" type=\"checkbox\" checked> 각자 특공+일반 동시신청</label>\n        <label class=\"checkline\"><input id=\"diversify\" type=\"checkbox\" checked> 신청자간 평형 분산</label>\n        <button id=\"calculate\" class=\"primary\">전략 다시 계산</button>\n      </div>\n\n      <div id=\"strategyWarning\"></div>\n      <div id=\"recommendation\"></div>\n\n      <article class=\"card result-card\">\n        <div class=\"card-head\"><div><span class=\"kicker\">GENERAL SUPPLY</span><h3>일반공급 실제 좌석</h3></div><span class=\"rounding\">소수점 올림 반영</span></div>\n        <div id=\"generalSeats\" class=\"table-wrap\"></div>\n      </article>\n\n      <article class=\"card result-card\">\n        <div class=\"card-head\"><div><span class=\"kicker\">SPECIAL SUPPLY</span><h3>특별공급 단계별 실제 좌석</h3></div><span class=\"rounding\">50% → 20% → 나머지</span></div>\n        <div id=\"specialSeats\" class=\"table-wrap\"></div>\n      </article>\n\n      <div class=\"grid two\">\n        <article class=\"card result-card\"><h3>신청자별 신청 후보 순위</h3><div id=\"candidateTable\" class=\"table-wrap\"></div></article>\n        <article class=\"card result-card\"><h3>자격 체크</h3><div id=\"eligibilityTable\" class=\"table-wrap\"></div></article>\n      </div>\n\n      <details class=\"legal-note\">\n        <summary>계산 원칙과 꼭 확인할 점</summary>\n        <div>\n          <p>이 계산기는 모집공고 물량을 법정 비율로 좌석화하고 상대적인 전략 우선순위를 비교합니다. 경쟁률이나 실제 당첨확률을 예측하지 않습니다.</p>\n          <p>특별공급 각 단계의 미달 좌석과 낙첨자는 다음 단계로 넘어가므로 실제 접수결과에 따라 후속 단계 좌석은 늘 수 있습니다. 최종 신청 전 청약Home과 사업주체에 자격을 확인하세요.</p>\n        </div>\n      </details>\n    </section>\n  </main>\n\n  <div id=\"toast\" class=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n  <script src=\"./rules.js\"></script>\n  <script src=\"./app.js\"></script>\n</body>\n</html>\n","type":"text/html; charset=utf-8"},"/styles.css":{"body":":root{--ink:#172019;--muted:#667068;--line:#dfe5df;--paper:#fff;--bg:#f3f5f0;--green:#174f3a;--green2:#e5f1ea;--lime:#cfe65a;--orange:#f28c45;--blue:#315caa;--red:#a83333;--shadow:0 12px 35px rgba(23,32,25,.07)}\n*{box-sizing:border-box}\nbody{margin:0;background:var(--bg);color:var(--ink);font-family:Pretendard,\"Noto Sans KR\",Arial,sans-serif;letter-spacing:-.015em}\nbutton,input,select{font:inherit}button{cursor:pointer}\n.hero{background:linear-gradient(125deg,#123c2c,#1b5d43);color:#fff;border-bottom:5px solid var(--lime)}\n.hero-inner{max-width:1240px;margin:auto;padding:34px 24px;display:flex;justify-content:space-between;gap:24px;align-items:flex-end}\n.eyebrow,.kicker{font-size:11px;letter-spacing:.14em;font-weight:900;text-transform:uppercase}.eyebrow{color:var(--lime)}\nh1{font-size:38px;margin:7px 0 8px;letter-spacing:-.045em}.hero p{margin:0;color:#d7e5dc;line-height:1.6}\n.privacy{font-size:12px;color:#d7e5dc;border:1px solid #ffffff36;border-radius:99px;padding:9px 13px;white-space:nowrap}.privacy span{color:var(--lime)}\n.shell{max-width:1240px;margin:auto;padding:0 24px 70px}.steps{display:grid;grid-template-columns:repeat(3,1fr);background:#fff;margin:-1px 0 28px;border:1px solid var(--line);border-top:0;border-radius:0 0 16px 16px;overflow:hidden}\n.step{border:0;border-right:1px solid var(--line);background:#fff;padding:17px 20px;display:grid;grid-template-columns:35px 1fr;grid-template-rows:1fr 1fr;text-align:left;color:var(--muted)}\n.step:last-child{border-right:0}.step b{grid-row:1/3;width:28px;height:28px;border-radius:50%;background:#eef1ec;display:grid;place-items:center;color:var(--muted)}.step span{font-weight:900;color:var(--ink)}.step small{font-size:11px}\n.step.active{background:var(--green2)}.step.active b{background:var(--green);color:#fff}.step.active span{color:var(--green)}\n.panel{display:none}.panel.active{display:block}.section-head{display:flex;align-items:center;justify-content:space-between;gap:20px;margin:24px 0 15px}.section-head h2{font-size:27px;margin:4px 0}.kicker{color:var(--green)}\n.save-state,.law-date,.rounding{font-size:12px;color:var(--muted)}.grid{display:grid;gap:16px}.grid.two{grid-template-columns:1fr 1fr}.card{background:var(--paper);border:1px solid var(--line);border-radius:17px;padding:20px;box-shadow:var(--shadow);margin-bottom:16px}.card h3{margin:0 0 16px;font-size:18px}.people{margin-top:16px}.person{border-top:5px solid var(--green)}.person-b{border-top-color:var(--blue)}\n.person-title{display:flex;align-items:center;gap:10px}.person-title span{width:30px;height:30px;border-radius:9px;background:var(--green);color:white;display:grid;place-items:center;font-weight:900}.person-b .person-title span{background:var(--blue)}\nlabel{display:block;position:relative;font-size:12px;font-weight:800;color:#455047}input,select{width:100%;margin-top:6px;padding:10px 11px;border:1px solid #cad3cb;border-radius:9px;background:#fff;color:var(--ink);outline:none}input:focus,select:focus{border-color:var(--green);box-shadow:0 0 0 3px #174f3a18}\n.suffix{position:absolute;right:12px;bottom:11px;color:var(--muted);font-weight:700}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:13px}.form-grid.four{grid-template-columns:repeat(4,1fr)}.checks{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:16px}.checks.compact{grid-template-columns:1fr 1fr}.checks label,.checkline{display:flex;align-items:center;gap:8px;font-weight:700}.checks input,.checkline input{width:auto;margin:0;accent-color:var(--green)}.hint{font-size:12px;line-height:1.6;color:var(--muted);margin:14px 0 0}\n.actions{display:flex;gap:10px;margin:20px 0}.actions.end{justify-content:flex-end}.actions.split{justify-content:space-between}.primary,.ghost,.file-button{border:0;border-radius:10px;padding:12px 17px;font-weight:900}.primary{background:var(--green);color:#fff}.primary:hover{background:#0f3e2c}.ghost{background:#fff;color:var(--ink);border:1px solid var(--line)}.ghost:hover{background:#f8faf7}\n.import-card{display:grid;grid-template-columns:1fr auto;gap:8px 24px;background:#14251d;color:#fff;border-radius:18px;padding:22px;margin-bottom:16px;align-items:center}.import-card strong{font-size:19px}.import-card p{margin:6px 0 0;color:#cbd8d0;font-size:13px}.file-button{background:var(--lime);color:#172019}.file-button input,.file-inline input{display:none}.parse-status{grid-column:1/-1;border-top:1px solid #ffffff24;padding-top:12px;color:#cbd8d0;font-size:12px}\n.notice-toolbar{display:flex;gap:8px;align-items:flex-end;flex-wrap:wrap;margin-bottom:16px}.notice-toolbar>label:first-child{min-width:260px}.file-inline{font-size:13px}.badge{padding:8px 12px;border-radius:99px;font-size:12px;font-weight:900}.badge.warn{color:#8a3e00;background:#fff0dc}.badge.ok{color:#075c38;background:#dff4e8}\n.card-head{display:flex;justify-content:space-between;align-items:center;gap:16px}.card-head h3{margin-bottom:4px}.card-head p{font-size:12px;color:var(--muted);margin:0 0 14px}.table-wrap{overflow-x:auto}\ntable{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:9px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top;white-space:nowrap}th{color:var(--muted);font-size:11px;background:#f7f9f5}tfoot td{font-weight:900;background:#f3f7f2}.supply-table input{min-width:65px;margin:0;padding:7px}.supply-table input.name{min-width:72px}.icon-delete{border:0;background:#f8eaea;color:var(--red);border-radius:7px;padding:7px 9px}\n.rule-card{border-left:5px solid var(--lime)}.rate-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}.formula{background:#f4f7ef;border-radius:10px;padding:11px 13px;margin:15px 0 0;font-size:12px;color:#415044}\n.strategy-settings{display:grid;grid-template-columns:160px 210px repeat(3,1fr) auto;align-items:end;gap:12px}.strategy-settings .checkline{padding-bottom:10px}.strategy-settings .primary{height:42px}\n.alert{padding:14px 16px;border-radius:12px;margin-bottom:16px;font-size:13px;line-height:1.6}.alert.warn{background:#fff0dc;color:#7b3906;border:1px solid #ffd8aa}.alert.bad{background:#fdeaea;color:#842d2d;border:1px solid #f5c5c5}\n.recommend-hero{background:#14251d;color:#fff;border-radius:20px;padding:24px;margin-bottom:16px}.recommend-hero .kicker{color:var(--lime)}.recommend-hero h3{font-size:24px;margin:8px 0}.recommend-hero>p{color:#cdd9d2;margin:0}.recommend-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:18px}.recommend-person{background:#ffffff0d;border:1px solid #ffffff20;border-radius:14px;padding:15px}.recommend-person h4{margin:0 0 11px;color:var(--lime)}.application{display:flex;justify-content:space-between;gap:15px;padding:9px 0;border-top:1px solid #ffffff18}.application:first-of-type{border-top:0}.application small{color:#bfcac3}.application b{text-align:right}\n.result-card{margin-top:16px}.seat-main{font-weight:900;font-size:14px}.muted{color:var(--muted)}.tag{display:inline-block;padding:4px 7px;border-radius:99px;background:var(--green2);color:var(--green);font-weight:900;font-size:10px}.tag.lottery{background:#e9eef9;color:var(--blue)}.tag.zero{background:#f1f2f0;color:#747b75}.bar{height:5px;background:#e7ebe6;border-radius:99px;margin-top:5px;overflow:hidden}.bar i{display:block;height:100%;background:var(--green)}\n.legal-note{background:#fff;border:1px solid var(--line);border-radius:14px;margin-top:16px}.legal-note summary{padding:15px 18px;font-weight:900;cursor:pointer}.legal-note div{padding:0 18px 10px;color:var(--muted);font-size:13px;line-height:1.7}\n.toast{position:fixed;left:50%;bottom:25px;transform:translate(-50%,30px);background:#14251d;color:#fff;padding:11px 16px;border-radius:10px;font-size:13px;opacity:0;pointer-events:none;transition:.2s}.toast.show{opacity:1;transform:translate(-50%,0)}\n@media(max-width:1000px){.strategy-settings{grid-template-columns:1fr 1fr 1fr}.form-grid.four{grid-template-columns:1fr 1fr}}\n@media(max-width:760px){.hero-inner{padding:25px 16px;display:block}.privacy{display:inline-block;margin-top:18px}.shell{padding:0 13px 45px}.steps{margin-bottom:18px}.step{padding:12px 8px;grid-template-columns:28px 1fr}.step b{width:23px;height:23px}.step small{display:none}h1{font-size:30px}.grid.two,.form-grid,.form-grid.four,.checks,.checks.compact,.rate-grid,.recommend-grid{grid-template-columns:1fr}.section-head{align-items:flex-start}.import-card{grid-template-columns:1fr}.file-button{text-align:center}.strategy-settings{grid-template-columns:1fr}.strategy-settings .checkline{padding:3px 0}.actions.split{flex-direction:column-reverse}.actions button{width:100%}}\n\n.date-control{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:6px;position:relative}.date-control input{grid-column:1}.calendar-button{grid-column:2;margin-top:6px;border:1px solid #cad3cb;background:#f7f9f5;color:var(--green);border-radius:9px;padding:0 11px;font-size:11px;font-weight:900}.native-date-picker{position:absolute!important;width:1px!important;height:1px!important;opacity:0!important;right:0;bottom:0;pointer-events:none}.manual-date[aria-invalid=\"true\"]{border-color:var(--red);box-shadow:0 0 0 3px #a8333318}\n\n.profile-type-card{border-top:5px solid var(--lime)}\n.profile-options{display:grid;grid-template-columns:repeat(5,1fr);gap:9px}\n.profile-options label{cursor:pointer}\n.profile-options input{position:absolute;opacity:0;pointer-events:none}\n.profile-options span{display:flex;min-height:74px;flex-direction:column;justify-content:center;gap:5px;padding:12px;border:1px solid var(--line);border-radius:12px;background:#f8faf7;transition:.15s}\n.profile-options b{font-size:13px;color:var(--ink)}\n.profile-options small{font-size:11px;color:var(--muted);font-weight:700}\n.profile-options input:checked+span{border-color:var(--green);background:var(--green2);box-shadow:0 0 0 2px #174f3a18}\n.profile-note{margin-top:12px;padding:11px 13px;border-radius:10px;background:#f4f7ef;color:#415044;font-size:12px;line-height:1.55}\n.is-hidden{display:none!important}\n.calc-summary,.income-summary{display:grid;gap:10px;margin-top:16px}\n.calc-summary{grid-template-columns:repeat(3,1fr)}\n.calc-summary>div,.income-summary>div{border:1px solid var(--line);border-radius:12px;background:#f8faf7;padding:13px}\n.calc-summary>div{display:flex;align-items:center;gap:11px}\n.calc-summary b{font-size:22px;color:var(--green)}\n.calc-summary span,.income-summary span{font-size:11px;font-weight:900;color:#455047;line-height:1.35}\n.calc-summary small,.income-summary small{color:var(--muted);font-weight:700}\n.income-card{border-left:5px solid var(--blue)}\n.income-summary{grid-template-columns:repeat(4,1fr)}\n.income-summary>div{display:flex;flex-direction:column;gap:6px}\n.income-summary b{font-size:18px;color:var(--ink)}\n.income-summary .income-percent{background:#e9eef9;border-color:#ccd8ef}\n.income-summary .income-percent b{font-size:25px;color:var(--blue)}\n.recommend-grid.one{grid-template-columns:1fr}\ninput:disabled{background:#eef1ec;color:#6c756e}\n@media(max-width:1000px){.profile-options{grid-template-columns:repeat(3,1fr)}.income-summary{grid-template-columns:1fr 1fr}}\n@media(max-width:760px){.profile-options,.calc-summary,.income-summary{grid-template-columns:1fr}.profile-options span{min-height:auto}.calc-summary>div{align-items:flex-start}}\n.profile-subfields{display:flex;align-items:flex-end;gap:14px;margin-top:12px}.profile-subfields>label:first-child{min-width:310px}.profile-subfields .checkline{padding:0 0 10px}@media(max-width:760px){.profile-subfields{display:grid;grid-template-columns:1fr}.profile-subfields>label:first-child{min-width:0}}\n\n.income-summary .income-thresholds{grid-column:1/-1;background:#f4f7ef}.income-summary .income-thresholds b{font-size:13px;line-height:1.7;color:#30483a}\n\n.score-results{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:14px}\n.score-results>div{border:1px solid var(--line);border-radius:13px;padding:13px;background:#f8faf7;display:grid;grid-template-columns:1fr auto;gap:5px 12px;align-items:center}\n.score-results span{font-size:11px;font-weight:900;color:var(--muted)}\n.score-results output{font-size:24px;font-weight:950;color:var(--green)}\n.person-b .score-results output{color:var(--blue)}\n.score-results small{grid-column:1/-1;color:var(--muted);font-size:11px;line-height:1.5}\n.field-help{display:block;margin-top:5px;color:var(--muted);font-size:10px;font-weight:700}\n@media(max-width:760px){.score-results{grid-template-columns:1fr}}","type":"text/css; charset=utf-8"},"/rules.js":{"body":"(function(root){\n  \"use strict\";\n\n  const TYPE_LABELS={agency:\"기관추천\",multi:\"다자녀\",newly:\"신혼부부\",elder:\"노부모부양\",first:\"생애최초\",baby:\"신생아\",general:\"일반공급\"};\n  const PROFILE_LABELS={single:\"미혼·자녀 없음\",single_parent:\"미혼·자녀 있음\",engaged:\"혼인 예정·미신고\",married:\"법률혼\",former:\"이혼·사별 등\"};\n  const INCOME_2025={\n    year:2025,\n    source:\"월계 중흥S-클래스 입주자모집공고\",\n    base100:{3:7533763,4:8802202,5:9326985,6:9906263,7:10485541,8:11064819},\n    incrementsAfter8:579278,\n    published:{\n      100:{3:7533763,4:8802202,5:9326985,6:9906263,7:10485541,8:11064819},\n      120:{3:9040516,4:10562642,5:11192382,6:11887516,7:12582649,8:13277783},\n      130:{3:9793892,4:11442863,5:12125081,6:12878142,7:13631203,8:14384265},\n      140:{3:10547268,4:12323083,5:13057779,6:13868768,7:14679757,8:15490747},\n      160:{3:12054021,4:14083523,5:14923176,6:15850021,7:16776866,8:17703710}\n    }\n  };\n\n  function integer(value){return Math.max(0,Math.floor(Number(value)||0));}\n  function clamp(value,min,max){return Math.max(min,Math.min(max,Number(value)||0));}\n  function won(value){return Math.max(0,Math.round(Number(value)||0));}\n\n  function pointRateForArea(area,rates){\n    const a=Number(area)||0;\n    if(a<=60)return clamp(rates.small,0,100);\n    if(a<=85)return clamp(rates.medium,0,100);\n    return clamp(rates.large,0,100);\n  }\n\n  function generalAllocation(supply,area,rates){\n    const total=integer(supply);\n    const pointRate=pointRateForArea(area,rates);\n    const point=Math.min(total,Math.ceil(total*pointRate/100));\n    const lottery=total-point;\n    const noHomePriority=Math.min(lottery,Math.ceil(lottery*.75));\n    return {total,area:Number(area)||0,pointRate,lotteryRate:100-pointRate,point,lottery,noHomePriority,lotteryRemainder:lottery-noHomePriority};\n  }\n\n  function specialAllocation(supply,firstRate=50,secondRate=20){\n    const total=integer(supply);\n    const stage1=Math.min(total,Math.ceil(total*clamp(firstRate,0,100)/100));\n    const stage2=Math.min(total-stage1,Math.ceil(total*clamp(secondRate,0,100)/100));\n    const stage3=Math.max(0,total-stage1-stage2);\n    return {total,stage1,stage2,stage3,firstRate:Number(firstRate),secondRate:Number(secondRate)};\n  }\n\n  function normalizeDate(value){\n    const raw=String(value||\"\").trim();\n    if(!raw)return \"\";\n    const digits=raw.replace(/\\D/g,\"\");\n    if(digits.length!==8)return \"\";\n    const normalized=`${digits.slice(0,4)}-${digits.slice(4,6)}-${digits.slice(6,8)}`;\n    const date=new Date(normalized+\"T00:00:00\");\n    if(Number.isNaN(date.getTime())||date.getFullYear()!==Number(digits.slice(0,4))||date.getMonth()+1!==Number(digits.slice(4,6))||date.getDate()!==Number(digits.slice(6,8)))return \"\";\n    return normalized;\n  }\n\n  function yearsBetween(from,to){\n    from=normalizeDate(from);to=normalizeDate(to);\n    if(!from||!to)return 0;\n    const a=new Date(from+\"T00:00:00\"),b=new Date(to+\"T00:00:00\");\n    if(Number.isNaN(a.getTime())||Number.isNaN(b.getTime())||b<a)return 0;\n    let years=b.getFullYear()-a.getFullYear();\n    const anniversaryPassed=b.getMonth()>a.getMonth()||(b.getMonth()===a.getMonth()&&b.getDate()>=a.getDate());\n    if(!anniversaryPassed)years--;\n    const lastAnniversary=new Date(a);lastAnniversary.setFullYear(a.getFullYear()+Math.max(0,years));\n    const nextAnniversary=new Date(lastAnniversary);nextAnniversary.setFullYear(lastAnniversary.getFullYear()+1);\n    const fraction=(b-lastAnniversary)/(nextAnniversary-lastAnniversary);\n    return Math.max(0,years+fraction);\n  }\n  function monthsBetween(from,to){return yearsBetween(from,to)*12;}\n\n  function profileType(profile){return PROFILE_LABELS[profile.profileType]?profile.profileType:\"single\";}\n  function hasLegalSpouse(profile){return profileType(profile)===\"married\";}\n  function hasSecondApplicant(profile){return hasLegalSpouse(profile);}\n  function specialChildCount(profile){return integer(profile.children)+integer(profile.fetuses);}\n  function generalChildCount(profile){return integer(profile.children);}\n  function automaticHouseholdSize(profile){\n    const adults=hasLegalSpouse(profile)?2:1;\n    return Math.max(1,adults+integer(profile.children)+integer(profile.fetuses));\n  }\n\n  function incomeBase100(size){\n    const count=Math.max(1,integer(size));\n    if(count<=3)return INCOME_2025.base100[3];\n    if(count<=8)return INCOME_2025.base100[count];\n    return INCOME_2025.base100[8]+INCOME_2025.incrementsAfter8*(count-8);\n  }\n  function publishedIncomeThreshold(size,pct){\n    const count=Math.max(1,integer(size));\n    if(count<=8&&INCOME_2025.published[pct])return INCOME_2025.published[pct][Math.max(3,count)];\n    return Math.round(incomeBase100(count)*Number(pct)/100);\n  }\n  function incomeMetrics(profile){\n    const size=Math.max(1,integer(profile.householdSize)||automaticHouseholdSize(profile));\n    const aIncome=won(profile.people?.a?.monthlyIncome);\n    const bIncome=hasLegalSpouse(profile)?won(profile.people?.b?.monthlyIncome):0;\n    const total=aIncome+bIncome;\n    const base=incomeBase100(size);\n    const pct=base?total/base*100:0;\n    const dualIncome=hasLegalSpouse(profile)&&aIncome>0&&bIncome>0;\n    return {year:INCOME_2025.year,size,aIncome,bIncome,total,base,pct,dualIncome,thresholds:{\n      100:publishedIncomeThreshold(size,100),120:publishedIncomeThreshold(size,120),130:publishedIncomeThreshold(size,130),140:publishedIncomeThreshold(size,140),160:publishedIncomeThreshold(size,160)\n    }};\n  }\n\n  function addYears(dateValue,years){\n    const normalized=normalizeDate(dateValue);\n    if(!normalized)return \"\";\n    const date=new Date(normalized+\"T00:00:00\");\n    const month=date.getMonth();\n    date.setFullYear(date.getFullYear()+years);\n    if(date.getMonth()!==month)date.setDate(0);\n    return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,\"0\")}-${String(date.getDate()).padStart(2,\"0\")}`;\n  }\n  function laterDate(...values){return values.map(normalizeDate).filter(Boolean).sort().pop()||\"\";}\n  function ownAccountPoints(account,noticeDate){\n    if(!normalizeDate(account)||!normalizeDate(noticeDate))return {points:0,years:0,complete:false};\n    const years=yearsBetween(account,noticeDate),months=years*12;\n    const points=months<6?1:months<12?2:Math.min(17,Math.floor(years)+2);\n    return {points,years,complete:true};\n  }\n  function spouseAccountPoints(account,noticeDate){\n    if(!normalizeDate(account)||!normalizeDate(noticeDate))return {points:0,years:0};\n    const years=yearsBetween(account,noticeDate);\n    return {points:years<1?1:years<2?2:3,years};\n  }\n  function generalNoHomePoints(person,profile,noticeDate){\n    const missing=[];\n    if(!profile.noHome)return {points:0,years:0,start:\"\",complete:true,missing};\n    if(!normalizeDate(person.birth)){missing.push(\"생년월일\");return {points:0,years:0,start:\"\",complete:false,missing};}\n    if(!normalizeDate(noticeDate)){missing.push(\"공고일\");return {points:0,years:0,start:\"\",complete:false,missing};}\n    const age30=addYears(person.birth,30);\n    const married=hasLegalSpouse(profile)&&normalizeDate(profile.marriageDate);\n    if(!married&&normalizeDate(noticeDate)<age30)return {points:0,years:0,start:age30,complete:true,missing};\n    let start=married&&normalizeDate(profile.marriageDate)<age30?normalizeDate(profile.marriageDate):age30;\n    if(!profile.neverHome){\n      const disposal=normalizeDate(profile.lastHomeDisposal);\n      if(!disposal){missing.push(\"최근 주택 처분일\");return {points:0,years:0,start:\"\",complete:false,missing};}\n      start=laterDate(start,disposal);\n    }\n    const years=yearsBetween(start,noticeDate);\n    const points=years>=15?32:years<1?2:Math.min(32,(Math.floor(years)+1)*2);\n    return {points,years,start,complete:true,missing};\n  }\n  function generalScore(personKey,profile,notice){\n    const person=profile.people[personKey];\n    const spouse=profile.people[personKey===\"a\"?\"b\":\"a\"];\n    const noHome=generalNoHomePoints(person,profile,notice.noticeDate);\n    const own=ownAccountPoints(person.account,notice.noticeDate);\n    const spouseAccount=hasLegalSpouse(profile)?spouseAccountPoints(spouse.account,notice.noticeDate):{points:0,years:0};\n    const accountPoints=Math.min(17,own.points+spouseAccount.points);\n    const childDependents=hasLegalSpouse(profile)||profile.unmarriedChildRegistered?integer(profile.children):0;\n    const dependents=Math.max(0,(hasLegalSpouse(profile)?1:0)+childDependents+integer(person.otherDependents));\n    const dependentPoints=Math.min(35,(Math.min(6,dependents)+1)*5);\n    const missing=[...noHome.missing];\n    if(!own.complete)missing.push(\"청약통장 가입일\");\n    return {points:noHome.points+dependentPoints+accountPoints,noHomePoints:noHome.points,noHomeYears:noHome.years,dependentPoints,dependents,accountPoints,ownAccountPoints:own.points,spouseAccountPoints:spouseAccount.points,complete:missing.length===0,missing:[...new Set(missing)]};\n  }\n  function multiNoHomePoints(person,profile,noticeDate){\n    const missing=[];\n    if(!profile.noHome)return {points:0,years:0,complete:true,missing};\n    if(!normalizeDate(person.birth)){missing.push(\"생년월일\");return {points:0,years:0,complete:false,missing};}\n    let start=addYears(person.birth,19);\n    if(!profile.neverHome){\n      const disposal=normalizeDate(profile.lastHomeDisposal);\n      if(!disposal){missing.push(\"최근 주택 처분일\");return {points:0,years:0,complete:false,missing};}\n      start=laterDate(start,disposal);\n    }\n    const years=yearsBetween(start,noticeDate);\n    return {points:years>=10?20:years>=5?15:years>=1?10:0,years,complete:true,missing};\n  }\n  function multiScore(personKey,profile,notice){\n    const person=profile.people[personKey];\n    const children=specialChildCount(profile);\n    const infants=integer(profile.infants)+integer(profile.fetuses);\n    const childPoints=children>=4?40:children===3?35:children===2?25:0;\n    const infantPoints=Math.min(15,infants*5);\n    const householdPoints=person.threeGeneration||person.singleParent5?5:0;\n    const noHome=multiNoHomePoints(person,profile,notice.noticeDate);\n    const residenceValid=normalizeDate(profile.residenceStart)&&normalizeDate(notice.noticeDate);\n    const residenceYears=residenceValid?yearsBetween(profile.residenceStart,notice.noticeDate):0;\n    const residencePoints=residenceYears>=10?15:residenceYears>=5?10:residenceYears>=1?5:0;\n    const accountValid=normalizeDate(person.account)&&normalizeDate(notice.noticeDate);\n    const accountYears=accountValid?yearsBetween(person.account,notice.noticeDate):0;\n    const accountPoints=accountYears>=10?5:0;\n    const missing=[...noHome.missing];\n    if(!residenceValid)missing.push(\"연속 거주 시작일\");\n    if(!accountValid)missing.push(\"청약통장 가입일\");\n    return {points:childPoints+infantPoints+householdPoints+noHome.points+residencePoints+accountPoints,childPoints,children,infantPoints,infants,householdPoints,noHomePoints:noHome.points,noHomeYears:noHome.years,residencePoints,residenceYears,accountPoints,accountYears,complete:missing.length===0,missing:[...new Set(missing)]};\n  }\n  function incomeStage(type,profile){\n    const income=incomeMetrics(profile);\n    const pct=income.pct;\n    if(type===\"newly\"){\n      const stage1Limit=income.dualIncome?120:100;\n      const stage2Limit=income.dualIncome?160:140;\n      const stage1IndividualOk=!income.dualIncome||Math.min(income.aIncome,income.bIncome)<=income.thresholds[100];\n      const stage2IndividualOk=!income.dualIncome||Math.min(income.aIncome,income.bIncome)<=income.thresholds[140];\n      if(income.total<=income.thresholds[stage1Limit]&&stage1IndividualOk)return {stage:1,label:\"1단계 우선공급\",reason:`가구소득 ${pct.toFixed(1)}%`,income};\n      if(income.total<=income.thresholds[stage2Limit]&&stage2IndividualOk)return {stage:2,label:\"2단계 일반공급\",reason:`가구소득 ${pct.toFixed(1)}%`,income};\n      if(profile.assetOk)return {stage:3,label:\"3단계 추첨공급\",reason:\"소득 초과·자산기준 충족\",income};\n      return {stage:0,label:\"소득·자산 부적격\",reason:\"상위소득은 자산기준 필요\",income};\n    }\n    if(type===\"first\"||type===\"baby\"){\n      if(income.total<=income.thresholds[130])return {stage:1,label:\"1단계 우선공급\",reason:`가구소득 ${pct.toFixed(1)}%`,income};\n      if(income.total<=income.thresholds[160])return {stage:2,label:\"2단계 일반공급\",reason:`가구소득 ${pct.toFixed(1)}%`,income};\n      if(profile.assetOk)return {stage:3,label:\"3단계 추첨공급\",reason:\"소득 초과·자산기준 충족\",income};\n      return {stage:0,label:\"소득·자산 부적격\",reason:\"상위소득은 자산기준 필요\",income};\n    }\n    return {stage:null,label:\"배점·순위\",reason:\"소득단계 없음\",income};\n  }\n\n  function profileSummary(profile,noticeDate){\n    const type=profileType(profile);\n    const marriageYears=hasLegalSpouse(profile)&&normalizeDate(profile.marriageDate)&&normalizeDate(noticeDate)?yearsBetween(profile.marriageDate,noticeDate):null;\n    let label=PROFILE_LABELS[type];\n    if(type===\"married\")label=profile.marriageDate?(marriageYears<=7?\"법률혼 · 혼인 7년 이내\":\"법률혼 · 혼인 7년 초과\"):\"법률혼 · 혼인신고일 입력 필요\";\n    return {type,label,marriageYears,legalSpouse:hasLegalSpouse(profile),secondApplicant:hasSecondApplicant(profile),specialChildren:specialChildCount(profile),generalChildren:generalChildCount(profile),automaticHouseholdSize:automaticHouseholdSize(profile)};\n  }\n\n  function eligibility(personKey,profile,notice){\n    const p=profile.people[personKey];\n    const type=profileType(profile);\n    const secondAllowed=personKey!==\"b\"||hasSecondApplicant(profile);\n    const accountMonths=monthsBetween(p.account,notice.noticeDate);\n    const marriageYears=hasLegalSpouse(profile)&&normalizeDate(profile.marriageDate)&&normalizeDate(notice.noticeDate)?yearsBetween(profile.marriageDate,notice.noticeDate):99;\n    const childAge=normalizeDate(profile.youngestBirth)&&normalizeDate(notice.noticeDate)?yearsBetween(profile.youngestBirth,notice.noticeDate):99;\n    const specialChildren=specialChildCount(profile);\n    const base=secondAllowed&&profile.noHome&&profile.specialClean&&profile.reWinClean&&p.deposit;\n    const headOk=notice.generalHeadRequired===\"no\"||p.head;\n    const firstRank=secondAllowed&&headOk&&profile.reWinClean&&p.deposit&&accountMonths>=Number(notice.generalMonths||24);\n    const registeredUnmarriedChild=integer(profile.children)>0&&Boolean(profile.unmarriedChildRegistered);\n    const normalFirstHome=hasLegalSpouse(profile)||registeredUnmarriedChild;\n    const singleHousehold=!hasLegalSpouse(profile)&&specialChildren===0;\n    const singleHouseholdAreaLimited=singleHousehold&&profile.singleHouseholdKind!==\"not_solo\";\n    const result={\n      agency:{ok:base&&p.agency&&accountMonths>=Number(notice.specialMonths||6),reason:p.agency?\"기관추천 확인\":\"기관추천 대상 확인 필요\"},\n      multi:{ok:base&&specialChildren>=2&&accountMonths>=Number(notice.specialMonths||6),reason:specialChildren>=2?`특공 자녀 ${specialChildren}명(태아 포함)`:\"태아 포함 미성년 자녀 2명 이상 필요\"},\n      newly:{ok:base&&type===\"married\"&&Boolean(profile.marriageDate)&&marriageYears<=7&&accountMonths>=Number(notice.specialMonths||6),reason:type!==\"married\"?\"법적 혼인신고가 된 배우자 필요\":!profile.marriageDate?\"혼인신고일 입력 필요\":marriageYears<=7?`혼인 ${marriageYears.toFixed(1)}년 · ${integer(profile.marriageChildren)>0?\"1순위\":\"2순위\"}`:\"혼인기간 7년 초과\",newlyRank:integer(profile.marriageChildren)>0?1:2},\n      elder:{ok:base&&firstRank&&p.elder3&&p.elderNoHome,reason:p.elder3&&p.elderNoHome?\"부양·무주택 확인\":\"노부모 3년 부양·무주택 확인 필요\"},\n      first:{ok:base&&firstRank&&profile.neverHome&&p.tax5&&(normalFirstHome||singleHousehold),reason:profile.neverHome&&p.tax5?(singleHousehold?(singleHouseholdAreaLimited?\"1인 단독세대 · 추첨 · 60㎡ 이하\":\"1인 비단독세대 · 추첨공급\"):!hasLegalSpouse(profile)&&specialChildren>0&&!registeredUnmarriedChild?\"미혼 자녀 주민등록표 등재 필요\":\"생애최초·소득세 요건 확인\"):\"과거소유·소득세 요건 확인 필요\",singleHousehold,singleHouseholdAreaLimited},\n      baby:{ok:base&&firstRank&&(integer(profile.fetuses)>0||childAge<=2),reason:integer(profile.fetuses)>0?`태아 ${integer(profile.fetuses)}명`:childAge<=2?`막내 ${childAge.toFixed(1)}세`:\"공고일 현재 2세 이하 자녀 또는 태아 필요\"},\n      general:{ok:firstRank,reason:firstRank?\"민영주택 1순위 입력요건 충족\":\"세대주·통장기간·예치금·당첨제한 확인\"}\n    };\n    if(!secondAllowed){Object.values(result).forEach(item=>{item.ok=false;item.reason=\"현재 프로필에는 법적 배우자 B가 없음\"});}\n    [\"newly\",\"first\",\"baby\"].forEach(supplyType=>{\n      const band=incomeStage(supplyType,profile);\n      result[supplyType].band=band;\n      if(band.stage===0){result[supplyType].ok=false;result[supplyType].reason=band.label;}\n    });\n    return result;\n  }\n\n  const api={TYPE_LABELS,PROFILE_LABELS,INCOME_2025,normalizeDate,pointRateForArea,generalAllocation,specialAllocation,yearsBetween,monthsBetween,profileType,hasLegalSpouse,hasSecondApplicant,specialChildCount,generalChildCount,automaticHouseholdSize,incomeBase100,publishedIncomeThreshold,incomeMetrics,addYears,ownAccountPoints,spouseAccountPoints,generalNoHomePoints,generalScore,multiNoHomePoints,multiScore,incomeStage,profileSummary,eligibility};\n  root.SubscriptionRules=api;\n  if(typeof module!==\"undefined\"&&module.exports)module.exports=api;\n})(typeof window!==\"undefined\"?window:globalThis);","type":"text/javascript; charset=utf-8"},"/app.js":{"body":"(function(){\n  \"use strict\";\n  const R=window.SubscriptionRules;\n  const $=id=>document.getElementById(id);\n  const clone=value=>JSON.parse(JSON.stringify(value));\n  const esc=value=>String(value??\"\").replace(/[&<>\"']/g,c=>({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]));\n  const num=(value,fallback=0)=>Number.isFinite(Number(value))?Number(value):fallback;\n  const sum=(rows,key)=>rows.reduce((total,row)=>total+num(row[key]),0);\n  const PROFILE_KEY=\"subscription_profile_v3\";\n  const NOTICES_KEY=\"subscription_notices_v3\";\n  const ACTIVE_KEY=\"subscription_active_notice_v3\";\n\n  const DEFAULT_NOTICE={\n    id:\"wolgyesclass-20260716\",\n    projectName:\"월계 중흥S-클래스 리비에르\",\n    noticeDate:\"2026-07-16\",\n    location:\"서울특별시 노원구\",\n    housingType:\"private\",\n    priorityRegion:\"서울특별시\",\n    priorityYears:2,\n    specialMonths:6,\n    generalMonths:24,\n    generalHeadRequired:\"yes\",\n    pointRates:{small:40,medium:70,large:80},\n    verified:true,\n    sourceFile:\"월계중흥S클래스.pdf\",\n    parseConfidence:100,\n    sizes:[\n      {name:\"36\",area:36.9533,total:20,agency:2,multi:2,newly:3,elder:0,first:1,baby:2,general:10},\n      {name:\"59A\",area:59.9667,total:71,agency:7,multi:7,newly:10,elder:2,first:5,baby:7,general:33},\n      {name:\"59B\",area:59.9424,total:42,agency:5,multi:5,newly:6,elder:1,first:3,baby:5,general:17},\n      {name:\"84A\",area:84.9807,total:2,agency:0,multi:0,newly:0,elder:0,first:0,baby:0,general:2}\n    ]\n  };\n\n  const PROFILE_IDS=[\n    \"residenceRegion\",\"residenceStart\",\"lastHomeDisposal\",\"noHome\",\"neverHome\",\"specialClean\",\"reWinClean\",\n    \"singleHouseholdKind\",\"unmarriedChildRegistered\",\"marriageDate\",\"children\",\"fetuses\",\"marriageChildren\",\"infants\",\"youngestBirth\",\"assetOk\",\n    \"householdSize\",\"householdSizeAuto\",\"aMonthlyIncome\",\"bMonthlyIncome\",\n    \"aAccount\",\"aBirth\",\"aOtherDependents\",\"aHead\",\"aDeposit\",\"aTax5\",\"aElder3\",\"aElderNoHome\",\"aAgency\",\"aThreeGeneration\",\"aSingleParent5\",\n    \"bAccount\",\"bBirth\",\"bOtherDependents\",\"bHead\",\"bDeposit\",\"bTax5\",\"bElder3\",\"bElderNoHome\",\"bAgency\",\"bThreeGeneration\",\"bSingleParent5\",\n    \"minArea\",\"mode\",\"bothApply\",\"allowSpecialGeneral\",\"diversify\"\n  ];\n  const CHECK_IDS=new Set([\"unmarriedChildRegistered\",\"noHome\",\"neverHome\",\"specialClean\",\"reWinClean\",\"assetOk\",\"aHead\",\"aDeposit\",\"aTax5\",\"aElder3\",\"aElderNoHome\",\"aAgency\",\"aThreeGeneration\",\"aSingleParent5\",\"bHead\",\"bDeposit\",\"bTax5\",\"bElder3\",\"bElderNoHome\",\"bAgency\",\"bThreeGeneration\",\"bSingleParent5\",\"bothApply\",\"allowSpecialGeneral\",\"diversify\"]);\n  const NOTICE_FIELDS=[\"projectName\",\"noticeDate\",\"location\",\"housingType\",\"priorityRegion\",\"priorityYears\",\"specialMonths\",\"generalMonths\",\"generalHeadRequired\"];\n  let notices=readStorage(NOTICES_KEY,{});\n  if(!Object.keys(notices).length)notices[DEFAULT_NOTICE.id]=clone(DEFAULT_NOTICE);\n  let activeId=localStorage.getItem(ACTIVE_KEY)||DEFAULT_NOTICE.id;\n  let notice=clone(notices[activeId]||DEFAULT_NOTICE);\n  let saveTimer;\n\n  function readStorage(key,fallback){\n    try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}\n  }\n  function toast(message){\n    $(\"toast\").textContent=message;$(\"toast\").classList.add(\"show\");\n    clearTimeout(toast.timer);toast.timer=setTimeout(()=>$(\"toast\").classList.remove(\"show\"),2200);\n  }\n  function setPanel(id){\n    document.querySelectorAll(\".panel,.step\").forEach(el=>el.classList.remove(\"active\"));\n    $(id).classList.add(\"active\");\n    document.querySelector(`.step[data-panel=\"${id}\"]`).classList.add(\"active\");\n    window.scrollTo({top:0,behavior:\"smooth\"});\n  }\n\n  function setupDateInputs(){\n    document.querySelectorAll(\".manual-date\").forEach(input=>{\n      const wrapper=document.createElement(\"span\");wrapper.className=\"date-control\";\n      input.parentNode.insertBefore(wrapper,input);wrapper.appendChild(input);\n      const picker=document.createElement(\"input\");picker.type=\"date\";picker.className=\"native-date-picker\";picker.tabIndex=-1;picker.setAttribute(\"aria-hidden\",\"true\");\n      const button=document.createElement(\"button\");button.type=\"button\";button.className=\"calendar-button\";button.setAttribute(\"aria-label\",\"달력에서 날짜 선택\");button.textContent=\"달력\";\n      wrapper.appendChild(button);wrapper.appendChild(picker);\n      const syncTyped=()=>{const value=R.normalizeDate(input.value);input.setAttribute(\"aria-invalid\",input.value&&!value?\"true\":\"false\");if(value)picker.value=value;return value};\n      input.addEventListener(\"input\",syncTyped);\n      input.addEventListener(\"blur\",()=>{const value=syncTyped();if(value){input.value=value;input.dispatchEvent(new Event(\"input\",{bubbles:true}))}});\n      picker.addEventListener(\"change\",()=>{input.value=picker.value;input.setAttribute(\"aria-invalid\",\"false\");input.dispatchEvent(new Event(\"input\",{bubbles:true}));input.dispatchEvent(new Event(\"change\",{bubbles:true}))});\n      button.addEventListener(\"click\",()=>{if(typeof picker.showPicker===\"function\")picker.showPicker();else picker.click()});\n    });\n  }\n\n  function selectedProfileType(){return document.querySelector('input[name=\"profileType\"]:checked')?.value||\"single\";}\n  function saveProfile(){\n    const data={profileType:selectedProfileType()};\n    PROFILE_IDS.forEach(id=>{const el=$(id);if(el)data[id]=CHECK_IDS.has(id)?el.checked:el.value});\n    localStorage.setItem(PROFILE_KEY,JSON.stringify(data));\n    $(\"profileSaveState\").textContent=\"저장됨 · \"+new Date().toLocaleTimeString(\"ko-KR\",{hour:\"2-digit\",minute:\"2-digit\"});\n  }\n  function queueProfileSave(){\n    $(\"profileSaveState\").textContent=\"저장 중…\";\n    clearTimeout(saveTimer);saveTimer=setTimeout(saveProfile,250);\n  }\n  function loadProfile(){\n    const data=readStorage(PROFILE_KEY,{});\n    if(!data.profileType&&data.marriageDate)data.profileType=\"married\";\n    if(data.pregnant&&data.fetuses===undefined)data.fetuses=\"1\";\n    Object.entries(data).forEach(([id,value])=>{\n      if(id===\"profileType\"){\n        const radio=document.querySelector(`input[name=\"profileType\"][value=\"${value}\"]`);\n        if(radio)radio.checked=true;\n        return;\n      }\n      const el=$(id);if(!el)return;\n      CHECK_IDS.has(id)?el.checked=Boolean(value):el.value=value;\n    });\n  }\n  function profileData(){\n    const v=id=>$(id).value;\n    const d=id=>R.normalizeDate($(id).value);\n    const c=id=>$(id).checked;\n    const person=key=>({\n      account:d(key+\"Account\"),monthlyIncome:num(v(key+\"MonthlyIncome\")),birth:d(key+\"Birth\"),otherDependents:num(v(key+\"OtherDependents\")),\n      head:c(key+\"Head\"),deposit:c(key+\"Deposit\"),tax5:c(key+\"Tax5\"),elder3:c(key+\"Elder3\"),elderNoHome:c(key+\"ElderNoHome\"),agency:c(key+\"Agency\"),\n      threeGeneration:c(key+\"ThreeGeneration\"),singleParent5:c(key+\"SingleParent5\")\n    });\n    const partial={\n      profileType:selectedProfileType(),singleHouseholdKind:v(\"singleHouseholdKind\"),unmarriedChildRegistered:c(\"unmarriedChildRegistered\"),residenceRegion:v(\"residenceRegion\"),residenceStart:d(\"residenceStart\"),lastHomeDisposal:d(\"lastHomeDisposal\"),\n      noHome:c(\"noHome\"),neverHome:c(\"neverHome\"),specialClean:c(\"specialClean\"),reWinClean:c(\"reWinClean\"),\n      marriageDate:d(\"marriageDate\"),children:num(v(\"children\")),fetuses:num(v(\"fetuses\")),marriageChildren:num(v(\"marriageChildren\")),infants:num(v(\"infants\")),\n      youngestBirth:d(\"youngestBirth\"),assetOk:c(\"assetOk\"),householdSize:num(v(\"householdSize\")),people:{a:person(\"a\"),b:person(\"b\")}\n    };\n    if(v(\"householdSizeAuto\")===\"yes\")partial.householdSize=R.automaticHouseholdSize(partial);\n    return partial;\n  }\n  function formatWon(value){return Math.round(num(value)).toLocaleString(\"ko-KR\")+\"원\";}\n  function renderProfileSummary(){\n    const profile=profileData();\n    const summary=R.profileSummary(profile,notice.noticeDate);\n    const income=R.incomeMetrics(profile);\n    const married=summary.legalSpouse;\n    const onePerson=!married&&summary.specialChildren===0;\n    $(\"marriageDateField\").classList.toggle(\"is-hidden\",!married);\n    $(\"lastHomeDisposalField\").classList.toggle(\"is-hidden\",profile.neverHome);\n    $(\"singleHouseholdKindField\").classList.toggle(\"is-hidden\",!onePerson);\n    $(\"unmarriedChildRegisteredField\").classList.toggle(\"is-hidden\",married||summary.specialChildren===0);\n    $(\"personBCard\").classList.toggle(\"is-hidden\",!married);\n    $(\"bIncomeField\").classList.toggle(\"is-hidden\",!married);\n    $(\"bothApplyField\").classList.toggle(\"is-hidden\",!married);\n    $(\"personBTitle\").textContent=married?\"배우자 B\":\"신청자 B\";\n    if(!married)$(\"bothApply\").checked=false;\n    if($(\"householdSizeAuto\").value===\"yes\")$(\"householdSize\").value=summary.automaticHouseholdSize;\n    $(\"householdSize\").disabled=$(\"householdSizeAuto\").value===\"yes\";\n    $(\"derivedProfileBadge\").textContent=summary.label;\n    const notes={\n      single:$(\"singleHouseholdKind\").value===\"solo\"?\"민영 생애최초는 1인 가구 추첨공급만 가능하며 단독세대는 전용 60㎡ 이하로 제한됩니다.\":\"미혼·무자녀 비단독세대는 생애최초 1인 가구 추첨공급을 검토합니다.\",\n      single_parent:\"법적 배우자는 없지만 미혼 자녀 요건에 따라 생애최초 일반유형을 검토합니다.\",\n      engaged:\"혼인신고 전에는 민영 신혼부부 특공의 배우자로 보지 않습니다. 현재 화면은 신청자 A 단독 기준입니다.\",\n      married:summary.marriageYears===null?\"혼인신고일을 넣으면 신혼부부 7년 요건을 자동 판정합니다.\":summary.marriageYears<=7?\"공고일 기준 혼인 7년 이내로 신혼부부 특공을 검토합니다.\":\"공고일 기준 혼인 7년을 초과해 신혼부부 특공 대상에서 제외합니다.\",\n      former:\"현재 법적 배우자가 없는 신청자 A 단독 기준으로 계산합니다.\"\n    };\n    $(\"profileTypeNote\").textContent=notes[summary.type];\n    $(\"childCountSummary\").innerHTML=`<div><b>${summary.specialChildren}명</b><span>특공 자녀 수<br><small>출생 ${profile.children} + 태아 ${profile.fetuses}</small></span></div><div><b>${summary.generalChildren}명</b><span>일반공급 자녀 수<br><small>주민등록된 출생자녀 기준</small></span></div><div><b>${summary.automaticHouseholdSize}명</b><span>소득 가구원 자동값<br><small>태아 포함</small></span></div>`;\n    const incomeBand=income.total<=income.thresholds[100]?\"100% 이하\":income.total<=income.thresholds[120]?\"100~120%\":income.total<=income.thresholds[130]?\"120~130%\":income.total<=income.thresholds[140]?\"130~140%\":income.total<=income.thresholds[160]?\"140~160%\":\"160% 초과\";\n    $(\"incomeSummary\").innerHTML=`<div><span>가구 합산 월소득</span><b>${formatWon(income.total)}</b><small>A ${formatWon(income.aIncome)}${married?` · B ${formatWon(income.bIncome)}`:\"\"}</small></div><div><span>100% 기준액</span><b>${formatWon(income.base)}</b><small>${income.size}인 가구 · 2025 기준</small></div><div class=\"income-percent\"><span>도시근로자 소득비율</span><b>${income.pct.toFixed(1)}%</b><small>${income.dualIncome?\"맞벌이\":\"외벌이·단독소득\"}</small></div><div><span>자동 구간</span><b>${incomeBand}</b><small>공고문 원단위 상한으로 판정</small></div><div class=\"income-thresholds\"><span>${income.size}인 가구 월소득 상한</span><b>100% ${formatWon(income.thresholds[100])} · 120% ${formatWon(income.thresholds[120])} · 130% ${formatWon(income.thresholds[130])} · 140% ${formatWon(income.thresholds[140])} · 160% ${formatWon(income.thresholds[160])}</b></div>`;\n    [\"a\",\"b\"].forEach(key=>{\n      const general=R.generalScore(key,profile,notice),multi=R.multiScore(key,profile,notice);\n      $(key+\"GeneralScore\").textContent=`${general.points}점`;\n      $(key+\"GeneralBreakdown\").textContent=`무주택 ${general.noHomePoints} + 부양가족 ${general.dependentPoints} + 통장 ${general.accountPoints}${general.complete?\"\":` · 입력 필요: ${general.missing.join(\", \")}`}`;\n      $(key+\"MultiScore\").textContent=`${multi.points}점`;\n      $(key+\"MultiBreakdown\").textContent=`자녀 ${multi.childPoints} + 영유아 ${multi.infantPoints} + 세대 ${multi.householdPoints} + 무주택 ${multi.noHomePoints} + 거주 ${multi.residencePoints} + 통장 ${multi.accountPoints}${multi.complete?\"\":` · 입력 필요: ${multi.missing.join(\", \")}`}`;\n    });\n  }\n\n  function refreshLibrary(){\n    $(\"noticeLibrary\").innerHTML=Object.values(notices).sort((a,b)=>String(b.noticeDate).localeCompare(String(a.noticeDate))).map(n=>`<option value=\"${esc(n.id)}\"${n.id===notice.id?\" selected\":\"\"}>${esc(n.projectName||\"이름 없는 공고\")} · ${esc(n.noticeDate||\"날짜 없음\")}</option>`).join(\"\");\n  }\n  function saveCurrentNotice(showToast=true){\n    if(!notice.id)notice.id=\"notice-\"+Date.now();\n    notices[notice.id]=clone(notice);\n    localStorage.setItem(NOTICES_KEY,JSON.stringify(notices));\n    localStorage.setItem(ACTIVE_KEY,notice.id);\n    activeId=notice.id;\n    refreshLibrary();\n    if(showToast)toast(\"현재 모집공고를 이 기기에 저장했습니다.\");\n  }\n  function markUnverified(){\n    notice.verified=false;\n    $(\"verifiedBadge\").className=\"badge warn\";\n    $(\"verifiedBadge\").textContent=\"검수 필요\";\n  }\n  function renderNotice(){\n    NOTICE_FIELDS.forEach(id=>{$(id).value=notice[id]??\"\"});\n    $(\"pointRateSmall\").value=notice.pointRates?.small??40;\n    $(\"pointRateMedium\").value=notice.pointRates?.medium??70;\n    $(\"pointRateLarge\").value=notice.pointRates?.large??80;\n    renderSupplyRows();\n    $(\"verifiedBadge\").className=\"badge \"+(notice.verified?\"ok\":\"warn\");\n    $(\"verifiedBadge\").textContent=notice.verified?\"검수 완료\":\"검수 필요\";\n    refreshLibrary();\n    if($(\"incomeSummary\"))renderProfileSummary();\n  }\n  function renderSupplyRows(){\n    $(\"supplyRows\").innerHTML=notice.sizes.map((row,index)=>`<tr data-index=\"${index}\">\n      <td><input class=\"name\" data-field=\"name\" value=\"${esc(row.name)}\"></td>\n      <td><input data-field=\"area\" type=\"number\" min=\"0\" step=\".0001\" value=\"${num(row.area)}\"></td>\n      <td><input data-field=\"total\" type=\"number\" min=\"0\" value=\"${num(row.total)}\"></td>\n      ${[\"agency\",\"multi\",\"newly\",\"elder\",\"first\",\"baby\",\"general\"].map(field=>`<td><input data-field=\"${field}\" type=\"number\" min=\"0\" value=\"${num(row[field])}\"></td>`).join(\"\")}\n      <td><button class=\"icon-delete\" data-delete=\"${index}\" aria-label=\"${esc(row.name)} 삭제\">×</button></td>\n    </tr>`).join(\"\");\n    renderSupplyTotal();\n  }\n  function renderSupplyTotal(){\n    const keys=[\"total\",\"agency\",\"multi\",\"newly\",\"elder\",\"first\",\"baby\",\"general\"];\n    $(\"supplyTotal\").innerHTML=`<tr><td>합계</td><td></td>${keys.map(key=>`<td>${sum(notice.sizes,key)}</td>`).join(\"\")}<td></td></tr>`;\n  }\n  function syncNoticeMeta(){\n    NOTICE_FIELDS.forEach(id=>notice[id]=[\"priorityYears\",\"specialMonths\",\"generalMonths\"].includes(id)?num($(id).value):id===\"noticeDate\"?R.normalizeDate($(id).value):$(id).value);\n    notice.pointRates={small:num($(\"pointRateSmall\").value),medium:num($(\"pointRateMedium\").value),large:num($(\"pointRateLarge\").value)};\n    markUnverified();\n    renderProfileSummary();\n  }\n\n  async function extractPdf(file){\n    $(\"parseStatus\").textContent=\"PDF 분석 도구를 불러오는 중…\";\n    const pdfjs=await import(\"https://cdn.jsdelivr.net/npm/pdfjs-dist@5.7.284/build/pdf.min.mjs\");\n    pdfjs.GlobalWorkerOptions.workerSrc=\"https://cdn.jsdelivr.net/npm/pdfjs-dist@5.7.284/build/pdf.worker.min.mjs\";\n    const pdf=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;\n    const pages=Math.min(pdf.numPages,25);\n    const lines=[];\n    for(let pageNo=1;pageNo<=pages;pageNo++){\n      $(\"parseStatus\").textContent=`PDF ${pageNo}/${pages}쪽에서 공급표와 규칙을 찾는 중…`;\n      const page=await pdf.getPage(pageNo);\n      const content=await page.getTextContent();\n      const groups=[];\n      content.items.filter(item=>item.str?.trim()).forEach(item=>{\n        const y=Math.round(item.transform[5]*2)/2;\n        let group=groups.find(g=>Math.abs(g.y-y)<=1.5);\n        if(!group){group={y,items:[]};groups.push(group)}\n        group.items.push({x:item.transform[4],text:item.str.trim()});\n      });\n      groups.sort((a,b)=>b.y-a.y).forEach(group=>{\n        group.items.sort((a,b)=>a.x-b.x);\n        lines.push(group.items.map(item=>item.text).join(\" \").replace(/\\s+/g,\" \").trim());\n      });\n    }\n    return {lines,pages,totalPages:pdf.numPages};\n  }\n\n  function parseSupplyRows(lines){\n    const candidates=[];\n    for(let i=0;i<lines.length;i++){\n      candidates.push(lines[i]);\n      if(i+1<lines.length)candidates.push(lines[i]+\" \"+lines[i+1]);\n    }\n    const found=new Map();\n    candidates.forEach(line=>{\n      const tokens=line.replace(/,/g,\"\").replace(/[–—]/g,\"-\").split(/\\s+/).filter(Boolean);\n      for(let start=0;start<=tokens.length-10;start++){\n        const tail=tokens.slice(start,start+10);\n        if(!tail.every(token=>token===\"-\"||/^\\d+$/.test(token)))continue;\n        const values=tail.map(token=>token===\"-\"?0:Number(token));\n        const [total,agency,multi,newly,elder,first,baby,specialTotal,general]=values;\n        if(total<=0||total>10000||specialTotal!==agency+multi+newly+elder+first+baby||total!==specialTotal+general)continue;\n        const prefix=tokens.slice(0,start);\n        let name=prefix.filter(token=>/^\\d{2,3}[A-Z]?$/.test(token)&&num(token.replace(/[A-Z]/g,\"\"))>=20&&num(token.replace(/[A-Z]/g,\"\"))<=200).pop();\n        const full=prefix.find(token=>/^0?\\d{2,3}\\.\\d{2,}[A-Z]?$/.test(token)&&num(token)>=20&&num(token)<=200);\n        if(!name&&full){const m=full.match(/^0?(\\d{2,3})\\.\\d+([A-Z]?)$/);if(m)name=String(Number(m[1]))+m[2]}\n        if(!name)continue;\n        const area=full?num(full.replace(/[A-Z]/g,\"\")):num(name.replace(/[A-Z]/g,\"\"));\n        const row={name,area,total,agency,multi,newly,elder,first,baby,general};\n        const prior=found.get(name);\n        if(!prior||prefix.length<prior._prefix){row._prefix=prefix.length;found.set(name,row)}\n      }\n    });\n    return [...found.values()].map(({_prefix,...row})=>row).sort((a,b)=>a.area-b.area||a.name.localeCompare(b.name));\n  }\n\n  function parseAnnouncement(lines,fileName){\n    const text=lines.join(\"\\n\");\n    const projectLine=lines.find(line=>/입주자\\s*모집공고/.test(line)&&line.length<90&&!/최초|현재|공고일/.test(line));\n    const projectName=(projectLine||fileName.replace(/\\.pdf$/i,\"\")).replace(/\\s*입주자\\s*모집공고.*$/,\"\").trim();\n    const dateContext=text.match(/입주자\\s*모집공고일[\\s\\S]{0,260}?(20\\d{2})[.\\-/년]\\s*(\\d{1,2})[.\\-/월]\\s*(\\d{1,2})/);\n    const anyDate=text.match(/(20\\d{2})[.\\-/년]\\s*(\\d{1,2})[.\\-/월]\\s*(\\d{1,2})/);\n    const dm=dateContext||anyDate;\n    const date=dm?`${dm[1]}-${String(dm[2]).padStart(2,\"0\")}-${String(dm[3]).padStart(2,\"0\")}`:\"\";\n    const locationLine=lines.find(line=>/공급위치\\s*:/.test(line));\n    const location=locationLine?locationLine.replace(/^.*공급위치\\s*:\\s*/,\"\").split(/\\s{2,}|\\(/)[0].trim():\"\";\n    let priorityRegion=\"\";\n    if(/서울특별시\\s*\\d+년\\s*이상/.test(text))priorityRegion=\"서울특별시\";\n    else if(/인천광역시\\s*\\d+년\\s*이상/.test(text))priorityRegion=\"인천광역시\";\n    else if(/경기도\\s*\\d+년\\s*이상/.test(text))priorityRegion=\"경기도\";\n    const yearMatch=text.match(new RegExp((priorityRegion||\"해당지역\").replace(/[.*+?^${}()|[\\]\\\\]/g,\"\\\\$&\")+\"\\\\s*(\\\\d+)년\\\\s*이상\"));\n    const sizes=parseSupplyRows(lines);\n    const oldByName=new Map(notice.sizes.map(row=>[row.name,row]));\n    const merged=sizes.map(row=>oldByName.has(row.name)?{...oldByName.get(row.name),...row}:row);\n    if(projectName.includes(\"월계 중흥\")&&!merged.some(row=>row.name===\"84A\"))merged.push(clone(DEFAULT_NOTICE.sizes.find(row=>row.name===\"84A\")));\n    const isPrivate=/민영/.test(text)||/민간택지/.test(text);\n    const overheated=/투기과열지구/.test(text);\n    const adjusted=/청약과열지역/.test(text);\n    const rates=isPrivate?{small:40,medium:70,large:overheated?80:adjusted?50:0}:{small:0,medium:0,large:0};\n    return {\n      id:\"notice-\"+Date.now(),projectName:projectName||\"이름 없는 공고\",noticeDate:date,location,\n      housingType:isPrivate?\"private\":/국민주택|공공주택/.test(text)?\"public\":\"unsupported\",\n      priorityRegion,priorityYears:yearMatch?num(yearMatch[1]):0,specialMonths:/6개월\\s*(?:이상|경과)/.test(text)?6:6,\n      generalMonths:/24개월\\s*(?:이상|경과)/.test(text)?24:12,generalHeadRequired:overheated||adjusted?\"yes\":\"no\",pointRates:rates,verified:false,\n      sourceFile:fileName,parseConfidence:sizes.length?Math.min(95,55+sizes.length*10):20,sizes:merged\n    };\n  }\n\n  function exportNotice(){\n    const blob=new Blob([JSON.stringify(notice,null,2)],{type:\"application/json\"});\n    const link=document.createElement(\"a\");\n    link.href=URL.createObjectURL(blob);\n    link.download=(notice.projectName||\"청약공고\").replace(/[\\\\/:*?\"<>|]/g,\"_\")+\".json\";\n    link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);\n  }\n\n  function residencePriority(profile){\n    const regionMatch=notice.priorityRegion&&profile.residenceRegion.includes(notice.priorityRegion.replace(/특별시|광역시|도$/,\"\"));\n    return Boolean(regionMatch&&R.yearsBetween(profile.residenceStart,notice.noticeDate)>=num(notice.priorityYears));\n  }\n  function generalSeatRows(){\n    return notice.sizes.map(size=>({...size,...R.generalAllocation(size.general,size.area,notice.pointRates)}));\n  }\n  function specialSeatRows(){\n    const rows=[];\n    notice.sizes.forEach(size=>[\"newly\",\"first\",\"baby\"].forEach(type=>{\n      if(num(size[type])>0)rows.push({...R.specialAllocation(size[type]),size:size.name,area:size.area,type});\n    }));\n    return rows;\n  }\n  function renderGeneralSeats(){\n    const rows=generalSeatRows();\n    $(\"generalSeats\").innerHTML=`<table><thead><tr><th>주택형</th><th>실제 전용</th><th>일반공급</th><th>가점 비율</th><th>가점 좌석</th><th>추첨 좌석</th><th>추첨 중 무주택 우선</th><th>잔여 추첨</th></tr></thead><tbody>${rows.map(row=>`<tr>\n      <td><b>${esc(row.name)}</b></td><td>${row.area.toFixed(4)}㎡</td><td>${row.total}</td><td>${row.pointRate}%</td>\n      <td><span class=\"tag\">${row.point}</span></td><td><span class=\"tag lottery\">${row.lottery}</span></td>\n      <td>${row.noHomePriority}</td><td>${row.lotteryRemainder}</td></tr>`).join(\"\")}</tbody>\n      <tfoot><tr><td>합계</td><td></td><td>${sum(rows,\"total\")}</td><td></td><td>${sum(rows,\"point\")}</td><td>${sum(rows,\"lottery\")}</td><td>${sum(rows,\"noHomePriority\")}</td><td>${sum(rows,\"lotteryRemainder\")}</td></tr></tfoot></table>`;\n  }\n  function renderSpecialSeats(){\n    const rows=specialSeatRows();\n    $(\"specialSeats\").innerHTML=rows.length?`<table><thead><tr><th>주택형</th><th>유형</th><th>유형물량</th><th>1단계 우선 50%</th><th>2단계 일반 20%</th><th>3단계 추첨</th><th>해석</th></tr></thead><tbody>${rows.map(row=>`<tr>\n      <td><b>${esc(row.size)}</b></td><td>${R.TYPE_LABELS[row.type]}</td><td>${row.total}</td>\n      <td><span class=\"tag\">${row.stage1}</span></td><td>${row.stage2}</td><td><span class=\"tag ${row.stage3?\"lottery\":\"zero\"}\">${row.stage3}</span></td>\n      <td class=\"muted\">${row.stage3?`올림 후 추첨 ${row.stage3}석`:\"소수점 올림으로 3단계 기본좌석 없음\"}</td></tr>`).join(\"\")}</tbody>\n      <tfoot><tr><td>합계</td><td></td><td>${sum(rows,\"total\")}</td><td>${sum(rows,\"stage1\")}</td><td>${sum(rows,\"stage2\")}</td><td>${sum(rows,\"stage3\")}</td><td>미달 좌석은 다음 단계 이월</td></tr></tfoot></table>`:\"<p class='muted'>단계형 특별공급 물량이 없습니다.</p>\";\n  }\n\n  function candidateRows(personKey,profile){\n    const personLabel=personKey===\"a\"?\"신청자 A\":\"배우자 B\";\n    const e=R.eligibility(personKey,profile,notice);\n    const generalScore=R.generalScore(personKey,profile,notice);\n    const multiScore=R.multiScore(personKey,profile,notice);\n    const priority=residencePriority(profile);\n    const mode=$(\"mode\").value,minArea=num($(\"minArea\").value);\n    const rows=[];\n    notice.sizes.forEach(size=>{\n      if(num(size.area)<minArea)return;\n      Object.keys(R.TYPE_LABELS).forEach(type=>{\n        const supply=num(size[type]);\n        if(!supply||!e[type]?.ok)return;\n        if(type===\"first\"&&e.first.singleHouseholdAreaLimited&&num(size.area)>60)return;\n        let seats=supply,seatText=`${supply}석`,score=25+Math.log2(supply+1)*12+(priority?12:0);\n        const reasons=[`배정 ${supply}석`,priority?\"해당지역 우선\":\"기타지역 경쟁\"];\n        if([\"newly\",\"first\",\"baby\"].includes(type)){\n          const alloc=R.specialAllocation(supply);\n          const stage=e[type].band.stage;\n          seats=stage===1?alloc.stage1+alloc.stage2+alloc.stage3:stage===2?alloc.stage2+alloc.stage3:alloc.stage3;\n          seatText=`${e[type].band.label} · 진입가능 ${seats}석`;\n          score+=stage===1?16:stage===2?8:0;\n          reasons.push(e[type].band.label,`현재단계 이후 ${seats}석`);\n          if(type===\"newly\"){score+=e.newly.newlyRank===1?10:-6;reasons.push(`신혼부부 ${e.newly.newlyRank}순위`);}\n          if(!seats)score-=35;\n        }\n        if(type===\"general\"){\n          const alloc=R.generalAllocation(supply,size.area,notice.pointRates);\n          seatText=`가점 ${alloc.point} + 추첨 ${alloc.lottery}`;\n          score+=(generalScore.points-45)*.45+alloc.lottery*1.4;\n          reasons.push(`가점 ${generalScore.points}점${generalScore.complete?\"\":\"(일부 입력 필요)\"}`,seatText);\n        }\n        if(type===\"multi\"){score+=(multiScore.points-50)*.4;reasons.push(`다자녀 ${multiScore.points}점${multiScore.complete?\"\":\"(일부 입력 필요)\"}`)}\n        if(mode===\"probability\")score-=num(size.area)*.04;\n        if(mode===\"quality\")score+=num(size.area)*.22;\n        if(mode===\"balance\")score+=Math.min(85,num(size.area))*.08;\n        rows.push({personKey,personLabel,type,size:size.name,area:size.area,supply,seats,seatText,reasons,score:Math.max(1,Math.min(99,score))});\n      });\n    });\n    return rows.sort((a,b)=>b.score-a.score);\n  }\n\n  function pickPlan(rows,avoidSize){\n    const specials=rows.filter(row=>row.type!==\"general\");\n    const generals=rows.filter(row=>row.type===\"general\");\n    const choose=list=>{\n      if(!$(\"diversify\").checked||!avoidSize)return list[0]||null;\n      return list.find(row=>row.size!==avoidSize&&row.score>=((list[0]?.score||0)-9))||list[0]||null;\n    };\n    let special=choose(specials),general=choose(generals);\n    if(!$(\"allowSpecialGeneral\").checked){\n      const best=[special,general].filter(Boolean).sort((a,b)=>b.score-a.score)[0]||null;\n      special=best?.type===\"general\"?null:best;general=best?.type===\"general\"?best:null;\n    }\n    return {special,general};\n  }\n  function appLine(label,row){\n    return `<div class=\"application\"><div><small>${label}</small><br>${row?esc(R.TYPE_LABELS[row.type]):\"미신청\"}</div><b>${row?`${esc(row.size)}<br><small>${esc(row.seatText)}</small>`:\"—\"}</b></div>`;\n  }\n  function renderRecommendation(aRows,bRows,profile){\n    const a=pickPlan(aRows);\n    const useB=R.hasSecondApplicant(profile)&&$(\"bothApply\").checked;\n    const anchor=a.special?.size||a.general?.size;\n    const b=useB?pickPlan(bRows,anchor):{special:null,general:null};\n    const top=[a.special,a.general,b.special,b.general].filter(Boolean);\n    if(!top.length){$(\"recommendation\").innerHTML=\"<div class='alert bad'>현재 입력으로 추천 가능한 신청이 없습니다. 자격과 통장기간을 확인하세요.</div>\";return}\n    $(\"recommendation\").innerHTML=`<div class=\"recommend-hero\">\n      <span class=\"kicker\">RECOMMENDED PLAN</span>\n      <h3>${esc(notice.projectName)} 신청안</h3>\n      <p>실제 좌석, 현재 진입단계, 지역우선과 입력점수를 함께 비교한 상대 전략입니다.</p>\n      <div class=\"recommend-grid ${useB?\"\":\"one\"}\">\n        <div class=\"recommend-person\"><h4>신청자 A</h4>${appLine(\"특별공급\",a.special)}${appLine(\"일반공급\",a.general)}</div>\n        ${useB?`<div class=\"recommend-person\"><h4>배우자 B</h4>${appLine(\"특별공급\",b.special)}${appLine(\"일반공급\",b.general)}</div>`:\"\"}\n      </div></div>`;\n  }\n  function renderCandidates(rows){\n    $(\"candidateTable\").innerHTML=rows.length?`<table><thead><tr><th>신청자</th><th>주택형·유형</th><th>실제 좌석</th><th>전략지수</th></tr></thead><tbody>${rows.slice(0,24).map(row=>`<tr>\n      <td>${row.personLabel}</td><td><b>${esc(row.size)} · ${R.TYPE_LABELS[row.type]}</b><br><span class=\"muted\">${esc(row.reasons.slice(1).join(\" · \"))}</span></td>\n      <td>${esc(row.seatText)}</td><td><span class=\"seat-main\">${row.score.toFixed(1)}</span><div class=\"bar\"><i style=\"width:${row.score}%\"></i></div></td></tr>`).join(\"\")}</tbody></table>`:\"<p class='muted'>추천 후보가 없습니다.</p>\";\n  }\n  function renderEligibility(profile){\n    const people=R.hasSecondApplicant(profile)?[\"a\",\"b\"]:[\"a\"];\n    const types=Object.keys(R.TYPE_LABELS);\n    $(\"eligibilityTable\").innerHTML=`<table><thead><tr><th>유형</th>${people.map(key=>`<th>${key===\"a\"?\"신청자 A\":\"배우자 B\"}</th>`).join(\"\")}</tr></thead><tbody>${types.map(type=>`<tr><td><b>${R.TYPE_LABELS[type]}</b></td>${people.map(key=>{\n      const item=R.eligibility(key,profile,notice)[type];\n      return `<td><span class=\"tag ${item.ok?\"\":\"zero\"}\">${item.ok?\"가능\":\"확인\"}</span><br><span class=\"muted\">${esc(item.reason)}${item.band?.stage?` · ${esc(item.band.label)}`:\"\"}</span></td>`;\n    }).join(\"\")}</tr>`).join(\"\")}</tbody></table>`;\n  }\n\n  function calculate(){\n    renderProfileSummary();saveProfile();\n    const profile=profileData();\n    const summary=R.profileSummary(profile,notice.noticeDate);\n    const warnings=[];\n    if(!notice.verified)warnings.push(\"이 공고의 자동 추출 숫자가 아직 검수되지 않았습니다.\");\n    if(notice.housingType!==\"private\")warnings.push(\"현재 전략 엔진은 민영주택 분양을 우선 지원합니다. 국민·공공주택은 선정규칙 모듈을 별도로 적용해야 합니다.\");\n    if(summary.type===\"engaged\")warnings.push(\"혼인 예정·미신고 상태는 민영 신혼부부 특별공급의 법적 배우자로 인정되지 않아 신청자 A 단독으로 계산했습니다.\");\n    if(summary.type===\"married\"&&!profile.marriageDate)warnings.push(\"혼인신고일이 없어 신혼부부 7년 요건을 판정할 수 없습니다.\");\n    $(\"strategyWarning\").innerHTML=warnings.map(message=>`<div class=\"alert warn\">${esc(message)}</div>`).join(\"\");\n    renderGeneralSeats();renderSpecialSeats();\n    const aRows=candidateRows(\"a\",profile),bRows=R.hasSecondApplicant(profile)?candidateRows(\"b\",profile):[];\n    renderRecommendation(aRows,bRows,profile);\n    renderCandidates([...aRows,...bRows].sort((a,b)=>b.score-a.score));\n    renderEligibility(profile);\n  }\n\n  document.querySelectorAll(\".step\").forEach(button=>button.addEventListener(\"click\",()=>setPanel(button.dataset.panel)));\n  document.querySelectorAll(\"[data-go]\").forEach(button=>button.addEventListener(\"click\",()=>setPanel(button.dataset.go)));\n  function onProfileInput(){renderProfileSummary();queueProfileSave();}\n  PROFILE_IDS.forEach(id=>$(id)?.addEventListener(\"input\",onProfileInput));\n  document.querySelectorAll('input[name=\"profileType\"]').forEach(input=>input.addEventListener(\"change\",onProfileInput));\n  NOTICE_FIELDS.concat([\"pointRateSmall\",\"pointRateMedium\",\"pointRateLarge\"]).forEach(id=>$(id).addEventListener(\"input\",syncNoticeMeta));\n\n  $(\"supplyRows\").addEventListener(\"input\",event=>{\n    const input=event.target.closest(\"[data-field]\");if(!input)return;\n    const index=num(input.closest(\"tr\").dataset.index),field=input.dataset.field;\n    notice.sizes[index][field]=field===\"name\"?input.value:num(input.value);\n    markUnverified();renderSupplyTotal();\n  });\n  $(\"supplyRows\").addEventListener(\"click\",event=>{\n    const button=event.target.closest(\"[data-delete]\");if(!button)return;\n    notice.sizes.splice(num(button.dataset.delete),1);markUnverified();renderSupplyRows();\n  });\n  $(\"addSize\").addEventListener(\"click\",()=>{notice.sizes.push({name:\"새 평형\",area:0,total:0,agency:0,multi:0,newly:0,elder:0,first:0,baby:0,general:0});markUnverified();renderSupplyRows()});\n  $(\"saveNotice\").addEventListener(\"click\",()=>saveCurrentNotice());\n  $(\"exportNotice\").addEventListener(\"click\",exportNotice);\n  $(\"noticeLibrary\").addEventListener(\"change\",event=>{\n    saveCurrentNotice(false);notice=clone(notices[event.target.value]);activeId=notice.id;localStorage.setItem(ACTIVE_KEY,activeId);renderNotice();toast(\"저장된 공고를 불러왔습니다.\");\n  });\n  $(\"blankNotice\").addEventListener(\"click\",()=>{\n    notice={...clone(DEFAULT_NOTICE),id:\"notice-\"+Date.now(),projectName:\"\",noticeDate:\"\",location:\"\",priorityRegion:\"\",priorityYears:0,verified:false,sourceFile:\"\",parseConfidence:0,sizes:[]};\n    renderNotice();toast(\"빈 공고를 만들었습니다.\");\n  });\n  $(\"pdfFile\").addEventListener(\"change\",async event=>{\n    const file=event.target.files[0];if(!file)return;\n    try{\n      const extracted=await extractPdf(file);\n      notice=parseAnnouncement(extracted.lines,file.name);\n      renderNotice();\n      $(\"parseStatus\").textContent=`${extracted.pages}쪽 분석 완료 · 주택형 ${notice.sizes.length}개 감지 · 신뢰도 ${notice.parseConfidence}%. 공급표 숫자를 원문과 대조해 주세요.`;\n      toast(\"PDF 분석 초안을 만들었습니다.\");\n    }catch(error){\n      console.error(error);\n      $(\"parseStatus\").textContent=\"PDF 자동 분석에 실패했습니다. 인터넷 연결을 확인하거나 빈 공고에 숫자를 직접 입력해 주세요.\";\n    }\n  });\n  $(\"jsonFile\").addEventListener(\"change\",async event=>{\n    const file=event.target.files[0];if(!file)return;\n    try{\n      const parsed=JSON.parse(await file.text());\n      if(!Array.isArray(parsed.sizes))throw new Error(\"sizes missing\");\n      notice={...clone(DEFAULT_NOTICE),...parsed,id:parsed.id||\"notice-\"+Date.now(),verified:false};\n      renderNotice();toast(\"JSON 공고를 불러왔습니다. 숫자를 검수해 주세요.\");\n    }catch{toast(\"올바른 공고 JSON 파일이 아닙니다.\")}\n  });\n  $(\"confirmNotice\").addEventListener(\"click\",()=>{\n    syncNoticeMeta();\n    const invalid=notice.sizes.some(row=>!row.name||num(row.area)<=0||num(row.total)!==sum([row],\"agency\")+sum([row],\"multi\")+sum([row],\"newly\")+sum([row],\"elder\")+sum([row],\"first\")+sum([row],\"baby\")+sum([row],\"general\"));\n    if(!notice.projectName||!notice.noticeDate||!notice.sizes.length||invalid){toast(\"단지명·공고일·평형별 총물량을 확인해 주세요.\");return}\n    notice.verified=true;saveCurrentNotice(false);renderNotice();calculate();setPanel(\"strategy\");toast(\"검수된 좌석으로 전략을 계산했습니다.\");\n  });\n  $(\"calculate\").addEventListener(\"click\",calculate);\n\n  setupDateInputs();loadProfile();renderNotice();renderProfileSummary();calculate();\n})();\n","type":"text/javascript; charset=utf-8"}};
export default {async fetch(request){const url=new URL(request.url);const file=FILES[url.pathname];if(!file)return new Response("Not found",{status:404});return new Response(file.body,{headers:{"content-type":file.type,"cache-control":"no-store","x-content-type-options":"nosniff"}})}};
